import { useState, useMemo } from 'react';
import { Plus, Search, Edit2, Trash2, Eye } from 'lucide-react';
import { ColumnDef } from '@tanstack/react-table';
import Card, { CardHeader, CardBody } from '@/components/common/Card';
import Button from '@/components/common/Button';
import Input from '@/components/common/Input';
import Select from '@/components/common/Select';
import DataTable from '@/components/common/DataTable';
import Modal from '@/components/common/Modal';
import Badge from '@/components/common/Badge';
import { useStore } from '@/store/useStore';
import { cn, generateId } from '@/utils';
import type { AssetEquipment } from '@/types';
import { generateAssetCode } from '@/mock/data';

export default function AssetList() {
  const { assetEquipments, addAssetEquipment, updateAssetEquipment, deleteAssetEquipment } = useStore();
  const [codeFilter, setCodeFilter] = useState('');
  const [nameFilter, setNameFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [detailModalOpen, setDetailModalOpen] = useState(false);
  const [viewingAsset, setViewingAsset] = useState<AssetEquipment | null>(null);
  const [editingAsset, setEditingAsset] = useState<AssetEquipment | null>(null);

  const [formData, setFormData] = useState({
    code: '',
    name: '',
    specification: '',
    unit: '',
    amount: 0,
    storageLocation: '',
    status: 'in_use' as 'in_use' | 'in_requisition' | 'scrapped' | 'written_off',
    remark: '',
  });

  const stats = useMemo(() => {
    const total = assetEquipments.length;
    const inUse = assetEquipments.filter(a => a.status === 'in_use').length;
    const inRequisition = assetEquipments.filter(a => a.status === 'in_requisition').length;
    const scrapped = assetEquipments.filter(a => a.status === 'scrapped').length;
    const totalValue = assetEquipments.reduce((sum, a) => sum + a.amount, 0);
    return { total, inUse, inRequisition, scrapped, totalValue };
  }, [assetEquipments]);

  const filteredData = assetEquipments
    .filter(a => !codeFilter || a.code.toLowerCase().includes(codeFilter.toLowerCase()))
    .filter(a => !nameFilter || a.name.toLowerCase().includes(nameFilter.toLowerCase()))
    .filter(a => !statusFilter || a.status === statusFilter);

  const columns: ColumnDef<AssetEquipment, unknown>[] = [
    { accessorKey: 'code', header: '设备编码' },
    { accessorKey: 'name', header: '设备名称' },
    { accessorKey: 'specification', header: '规格型号' },
    { accessorKey: 'unit', header: '单位' },
    {
      accessorKey: 'amount',
      header: '金额',
      cell: ({ row }) => `¥${row.original.amount.toLocaleString()}`,
    },
    { accessorKey: 'storageLocation', header: '存放地点' },
    {
      accessorKey: 'status',
      header: '状态',
      cell: ({ row }) => {
        const status = row.original.status;
        const variants: Record<string, 'default' | 'success' | 'danger' | 'warning'> = {
          in_use: 'success',
          in_requisition: 'warning',
          scrapped: 'danger',
          written_off: 'default',
        };
        const labels: Record<string, string> = {
          in_use: '在用',
          in_requisition: '领用中',
          scrapped: '已报废',
          written_off: '已报损',
        };
        return <Badge variant={variants[status]}>{labels[status]}</Badge>;
      },
    },
    { accessorKey: 'createTime', header: '入账日期' },
    {
      id: 'actions',
      header: '操作',
      cell: ({ row }) => (
        <div className="flex items-center gap-2 flex-wrap">
          <Button variant="ghost" size="sm" onClick={() => handleView(row.original)}>查看</Button>
          <Button variant="ghost" size="sm" onClick={() => handleEdit(row.original)}>编辑</Button>
          <Button variant="ghost" size="sm" onClick={() => handleDelete(row.original)}><span className="text-red-500">删除</span></Button>
        </div>
      ),
    },
  ];

  const handleOpenModal = (asset?: AssetEquipment) => {
    if (asset) {
      setEditingAsset(asset);
      setFormData({
        code: asset.code,
        name: asset.name,
        specification: asset.specification || '',
        unit: asset.unit,
        amount: asset.amount,
        storageLocation: asset.storageLocation,
        status: asset.status,
        remark: asset.remark || '',
      });
    } else {
      setEditingAsset(null);
      setFormData({
        code: generateAssetCode(),
        name: '',
        specification: '',
        unit: '台',
        amount: 0,
        storageLocation: '',
        status: 'in_use',
        remark: '',
      });
    }
    setModalOpen(true);
  };

  const handleView = (asset: AssetEquipment) => {
    setViewingAsset(asset);
    setDetailModalOpen(true);
  };

  const handleEdit = (asset: AssetEquipment) => {
    handleOpenModal(asset);
  };

  const handleDelete = (asset: AssetEquipment) => {
    if (confirm(`确认删除设备"${asset.name}"吗？`)) {
      deleteAssetEquipment(asset.id);
    }
  };

  const handleSubmit = () => {
    if (!formData.name) {
      alert('请填写设备名称');
      return;
    }

    if (editingAsset) {
      updateAssetEquipment(editingAsset.id, {
        ...formData,
      });
    } else {
      addAssetEquipment({
        id: generateId(),
        ...formData,
        createTime: new Date().toISOString().slice(0, 10),
      });
    }
    setModalOpen(false);
  };

  const statusOptions = [
    { value: '', label: '全部状态' },
    { value: 'in_use', label: '在用' },
    { value: 'in_requisition', label: '领用中' },
    { value: 'scrapped', label: '已报废' },
    { value: 'written_off', label: '已报损' },
  ];

  const statusBadgeVariants: Record<string, 'default' | 'success' | 'danger' | 'warning'> = {
    in_use: 'success',
    in_requisition: 'warning',
    scrapped: 'danger',
    written_off: 'default',
  };

  const statusLabels: Record<string, string> = {
    in_use: '在用',
    in_requisition: '领用中',
    scrapped: '已报废',
    written_off: '已报损',
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-900">资产档案管理</h1>
        <Button onClick={() => handleOpenModal()}>
          <Plus size={16} />
          新增资产
        </Button>
      </div>

      {/* 统计卡片 */}
      <div className="grid grid-cols-5 gap-4">
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">资产总数</div>
            <div className="text-2xl font-bold text-slate-900">{stats.total}</div>
            <div className="text-xs text-slate-400 mt-1">台/套</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">在用资产</div>
            <div className="text-2xl font-bold text-green-600">{stats.inUse}</div>
            <div className="text-xs text-slate-400 mt-1">台/套</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">领用中</div>
            <div className="text-2xl font-bold text-yellow-600">{stats.inRequisition}</div>
            <div className="text-xs text-slate-400 mt-1">台/套</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">已报废</div>
            <div className="text-2xl font-bold text-red-600">{stats.scrapped}</div>
            <div className="text-xs text-slate-400 mt-1">台/套</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">资产总值</div>
            <div className="text-2xl font-bold text-blue-600">¥{stats.totalValue.toLocaleString()}</div>
            <div className="text-xs text-slate-400 mt-1">全部资产</div>
          </CardBody>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-4 flex-wrap">
            <div className="relative">
              <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input
                placeholder="设备编码..."
                value={codeFilter}
                onChange={(e) => setCodeFilter(e.target.value)}
                className="pl-9 w-48"
              />
            </div>
            <div className="relative">
              <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input
                placeholder="设备名称..."
                value={nameFilter}
                onChange={(e) => setNameFilter(e.target.value)}
                className="pl-9 w-48"
              />
            </div>
            <Select
              options={statusOptions}
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              placeholder="全部状态"
            />
          </div>
        </CardHeader>
        <CardBody>
          <DataTable data={filteredData} columns={columns} pageSize={10} />
        </CardBody>
      </Card>

      {/* 新增/编辑模态框 */}
      <Modal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        title={editingAsset ? '编辑资产' : '新增资产'}
        size="lg"
      >
        <div className="space-y-4 min-w-[600px]">
          <div className="grid grid-cols-2 gap-4">
            <Input
              label="设备编码"
              value={formData.code}
              onChange={(e) => setFormData({ ...formData, code: e.target.value })}
              disabled
            />
            <Input
              label="设备名称"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              placeholder="请输入设备名称"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <Input
              label="规格型号"
              value={formData.specification}
              onChange={(e) => setFormData({ ...formData, specification: e.target.value })}
              placeholder="请输入规格型号"
            />
          </div>
          <div className="grid grid-cols-3 gap-4">
            <Input
              label="计量单位"
              value={formData.unit}
              onChange={(e) => setFormData({ ...formData, unit: e.target.value })}
              placeholder="如：台、辆"
            />
            <Input
              label="金额"
              type="number"
              value={formData.amount || ''}
              onChange={(e) => setFormData({ ...formData, amount: parseFloat(e.target.value) || 0 })}
              placeholder="0.00"
            />
            <Select
              label="状态"
              options={statusOptions.filter(o => o.value !== '')}
              value={formData.status}
              onChange={(e) => setFormData({ ...formData, status: e.target.value as any })}
            />
          </div>
          <Input
            label="存放地点"
            value={formData.storageLocation}
            onChange={(e) => setFormData({ ...formData, storageLocation: e.target.value })}
            placeholder="如：车间A区"
          />
          <Input
            label="备注"
            value={formData.remark}
            onChange={(e) => setFormData({ ...formData, remark: e.target.value })}
            placeholder="备注信息"
          />
          <div className="flex justify-end gap-3 pt-2">
            <Button variant="secondary" onClick={() => setModalOpen(false)}>
              取消
            </Button>
            <Button onClick={handleSubmit}>
              保存
            </Button>
          </div>
        </div>
      </Modal>

      {/* 查看详情模态框 */}
      <Modal
        open={detailModalOpen}
        onClose={() => setDetailModalOpen(false)}
        title="资产详情"
        size="lg"
      >
        {viewingAsset && (
          <div className="space-y-4 min-w-[600px]">
            <div className="grid grid-cols-2 gap-4 text-sm">
              <div><span className="text-slate-500">设备编码：</span>{viewingAsset.code}</div>
              <div><span className="text-slate-500">设备名称：</span>{viewingAsset.name}</div>
              <div><span className="text-slate-500">规格型号：</span>{viewingAsset.specification || '-'}</div>
              <div><span className="text-slate-500">计量单位：</span>{viewingAsset.unit}</div>
              <div><span className="text-slate-500">金额：</span>¥{viewingAsset.amount.toLocaleString()}</div>
              <div><span className="text-slate-500">存放地点：</span>{viewingAsset.storageLocation}</div>
              <div><span className="text-slate-500">状态：</span>
                <Badge variant={statusBadgeVariants[viewingAsset.status]}>
                  {statusLabels[viewingAsset.status]}
                </Badge>
              </div>
              <div><span className="text-slate-500">入账日期：</span>{viewingAsset.createTime}</div>
              <div><span className="text-slate-500">备注：</span>{viewingAsset.remark || '-'}</div>
            </div>
            <div className="flex justify-end pt-2">
              <Button variant="secondary" onClick={() => setDetailModalOpen(false)}>
                关闭
              </Button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}
