import { useMemo, useState } from 'react';
import { PrimaryButton, DefaultButton, TextButton } from '@/components/common/Button';
import { SearchBar, SearchField } from '@/components/common/SearchField';
import { DataTable, ColumnDef } from '@/components/common/DataTable';
import Modal from '@/components/common/Modal';
import SearchableSelect from '@/components/common/SearchableSelect';
import { useStore } from '@/store/useStore';
import type { AssetEquipment } from '@/types';
import { generateAssetCode } from '@/mock/data';
import { generateId } from '@/utils';
import { Eye, Check, Trash2, Plus } from 'lucide-react';

interface AssetInboundOrder {
  id: string;
  orderNo: string;
  assetId: string;
  assetCode: string;
  assetName: string;
  specification: string;
  unit: string;
  quantity: number;
  amount: number;
  status: 'pending' | 'completed' | 'cancelled';
  inboundDate: string;
  operator: string;
  remark: string;
  createTime: string;
}

const generateAssetInboundNo = (): string => {
  const date = new Date();
  const dateStr = date.toISOString().slice(0, 10).replace(/-/g, '');
  const random = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
  return `ZCRK${dateStr}${random}`;
};

const mockInboundOrders: AssetInboundOrder[] = [
  {
    id: 'ZCRK001',
    orderNo: 'ZCRK20240601001',
    assetId: 'AE001',
    assetCode: 'SB20240001',
    assetName: '数控车床',
    specification: 'CJK6136',
    unit: '台',
    quantity: 1,
    amount: 150000,
    status: 'completed',
    inboundDate: '2024-06-01',
    operator: '张三',
    remark: '新购置设备入库',
    createTime: '2024-06-01 09:30:00',
  },
  {
    id: 'ZCRK002',
    orderNo: 'ZCRK20240615001',
    assetId: 'AE005',
    assetCode: 'SB20240005',
    assetName: '叉车',
    specification: 'CPCD30',
    unit: '辆',
    quantity: 1,
    amount: 68000,
    status: 'pending',
    inboundDate: '2024-06-15',
    operator: '李四',
    remark: '待审核',
    createTime: '2024-06-15 14:20:00',
  },
  {
    id: 'ZCRK003',
    orderNo: 'ZCRK20240620001',
    assetId: 'AE003',
    assetCode: 'SB20240003',
    assetName: '激光切割机',
    specification: 'LCT-3015',
    unit: '台',
    quantity: 1,
    amount: 280000,
    status: 'pending',
    inboundDate: '2024-06-20',
    operator: '王五',
    remark: '采购入库待审核',
    createTime: '2024-06-20 10:15:00',
  },
];

export default function AssetInbound() {
  const assetEquipments = useStore((s) => s.assetEquipments);
  const employees = useStore((s) => s.employees);
  const updateAssetEquipment = useStore((s) => s.updateAssetEquipment);
  const addAssetEquipment = useStore((s) => s.addAssetEquipment);
  const currentUser = useStore((s) => s.currentUser);

  const [inboundOrders, setInboundOrders] = useState<AssetInboundOrder[]>(mockInboundOrders);

  const [filterOrderNo, setFilterOrderNo] = useState('');
  const [filterAssetName, setFilterAssetName] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [filterFrom, setFilterFrom] = useState('');
  const [filterTo, setFilterTo] = useState('');
  const [applied, setApplied] = useState({ orderNo: '', assetName: '', status: '', from: '', to: '' });

  const [viewItem, setViewItem] = useState<AssetInboundOrder | null>(null);
  const [editItem, setEditItem] = useState<AssetInboundOrder | null>(null);
  const [pickerOpen, setPickerOpen] = useState(false);
  const [isNewAssetMode, setIsNewAssetMode] = useState(false);
  const [newAssetName, setNewAssetName] = useState('');
  const [newAssetSpecification, setNewAssetSpecification] = useState('');
  const [newAssetUnit, setNewAssetUnit] = useState('台');
  const [newAssetAmount, setNewAssetAmount] = useState(0);
  const [newAssetStorageLocation, setNewAssetStorageLocation] = useState('');
  const [newAssetRemark, setNewAssetRemark] = useState('');

  const [editAssetId, setEditAssetId] = useState('');
  const [editAssetCode, setEditAssetCode] = useState('');
  const [editAssetName, setEditAssetName] = useState('');
  const [editSpecification, setEditSpecification] = useState('');
  const [editUnit, setEditUnit] = useState('');
  const [editQuantity, setEditQuantity] = useState(1);
  const [editAmount, setEditAmount] = useState(0);
  const [editInboundDate, setEditInboundDate] = useState('');
  const [editOperator, setEditOperator] = useState('');
  const [editRemark, setEditRemark] = useState('');

  const statusText = (s: string) => {
    if (s === 'pending') return '待入库';
    if (s === 'completed') return '已入库';
    if (s === 'cancelled') return '已取消';
    return s;
  };

  const statusColor = (s: string) => {
    if (s === 'pending') return 'text-[#e6a23c]';
    if (s === 'completed') return 'text-[#67c23a]';
    if (s === 'cancelled') return 'text-[#909399]';
    return 'text-[#606266]';
  };

  const empOptions = employees
    .filter((e: any) => e.status === 'enabled')
    .map((e: any) => ({ id: e.id, label: e.name, role: e.role }));

  const employeeNameById = (id: string) => {
    const e = employees.find((x: any) => x.id === id);
    return e ? (e as any).name : '';
  };

  const stats = useMemo(() => {
    const today = new Date().toISOString().slice(0, 10);
    const thisMonth = new Date().toISOString().slice(0, 7);
    const todayCount = inboundOrders.filter(o => o.inboundDate === today).length;
    const monthCount = inboundOrders.filter(o => o.inboundDate.startsWith(thisMonth)).length;
    const pendingCount = inboundOrders.filter(o => o.status === 'pending').length;
    const completedCount = inboundOrders.filter(o => o.status === 'completed').length;
    return { todayCount, monthCount, pendingCount, completedCount };
  }, [inboundOrders]);

  const filteredData = useMemo(() => {
    return inboundOrders.filter((o) => {
      if (applied.orderNo && !o.orderNo.includes(applied.orderNo)) return false;
      if (applied.assetName && !o.assetName.includes(applied.assetName)) return false;
      if (applied.status && o.status !== applied.status) return false;
      if (applied.from && o.inboundDate < applied.from) return false;
      if (applied.to && o.inboundDate > applied.to) return false;
      return true;
    });
  }, [inboundOrders, applied]);

  const columns: ColumnDef<AssetInboundOrder>[] = [
    { key: 'orderNo', title: '入库单号' },
    { key: 'assetName', title: '资产名称' },
    { key: 'specification', title: '规格型号' },
    { key: 'unit', title: '单位' },
    { key: 'quantity', title: '数量', align: 'right' },
    {
      key: 'amount',
      title: '金额',
      align: 'right',
      render: (row) => `¥${row.amount.toLocaleString()}`,
    },
    {
      key: 'status',
      title: '入库状态',
      render: (row) => (
        <span className={statusColor(row.status)}>{statusText(row.status)}</span>
      ),
    },
    { key: 'inboundDate', title: '入库日期' },
    {
      key: 'op',
      title: '操作',
      render: (row) => (
        <div className="flex items-center gap-2 flex-wrap">
          <TextButton onClick={() => setViewItem(row)}>
            <Eye size={12} /> 查看
          </TextButton>
          {row.status === 'pending' && (
            <>
              <TextButton onClick={() => handleApprove(row.id)}>
                <Check size={12} /> 审核
              </TextButton>
              <TextButton type="danger" onClick={() => handleDelete(row.id)}>
                <Trash2 size={12} /> 删除
              </TextButton>
            </>
          )}
        </div>
      ),
    },
  ];

  const openAdd = () => {
    const newOrder: AssetInboundOrder = {
      id: 'ZCRK' + Date.now(),
      orderNo: generateAssetInboundNo(),
      assetId: '',
      assetCode: '',
      assetName: '',
      specification: '',
      unit: '',
      quantity: 1,
      amount: 0,
      status: 'pending',
      inboundDate: new Date().toISOString().slice(0, 10),
      operator: currentUser.name,
      remark: '',
      createTime: new Date().toISOString().slice(0, 10) + ' ' + new Date().toTimeString().slice(0, 5),
    };
    setEditItem(newOrder);
    setEditAssetId('');
    setEditAssetCode('');
    setEditAssetName('');
    setEditSpecification('');
    setEditUnit('');
    setEditQuantity(1);
    setEditAmount(0);
    setEditInboundDate(newOrder.inboundDate);
    setEditOperator(currentUser.name);
    setEditRemark('');
    setIsNewAssetMode(false);
    setNewAssetName('');
    setNewAssetSpecification('');
    setNewAssetUnit('台');
    setNewAssetAmount(0);
    setNewAssetStorageLocation('');
    setNewAssetRemark('');
  };

  const handleSelectAsset = (asset: AssetEquipment) => {
    setEditAssetId(asset.id);
    setEditAssetCode(asset.code);
    setEditAssetName(asset.name);
    setEditSpecification(asset.specification || '');
    setEditUnit(asset.unit);
    setEditAmount(asset.amount);
    setPickerOpen(false);
  };

  const handleAddNewAsset = () => {
    if (!newAssetName) {
      alert('请填写资产名称');
      return;
    }

    const newAssetId = generateId();
    const newAssetCode = generateAssetCode();

    const newAsset: AssetEquipment = {
      id: newAssetId,
      code: newAssetCode,
      name: newAssetName,
      specification: newAssetSpecification,
      unit: newAssetUnit,
      amount: newAssetAmount,
      storageLocation: newAssetStorageLocation,
      status: 'in_use',
      remark: newAssetRemark,
      createTime: new Date().toISOString().slice(0, 10),
    };

    addAssetEquipment(newAsset);

    setEditAssetId(newAssetId);
    setEditAssetCode(newAssetCode);
    setEditAssetName(newAssetName);
    setEditSpecification(newAssetSpecification || '');
    setEditUnit(newAssetUnit);
    setEditAmount(newAssetAmount);
    setPickerOpen(false);
    setIsNewAssetMode(false);
    setNewAssetName('');
    setNewAssetSpecification('');
    setNewAssetUnit('台');
    setNewAssetAmount(0);
    setNewAssetStorageLocation('');
    setNewAssetRemark('');
  };

  const handleSave = () => {
    if (!editItem) return;
    if (!editAssetId) { alert('请选择资产'); return; }
    if (!editQuantity || editQuantity <= 0) { alert('数量必须大于0'); return; }

    const updatedOrder: AssetInboundOrder = {
      ...editItem,
      assetId: editAssetId,
      assetCode: editAssetCode,
      assetName: editAssetName,
      specification: editSpecification,
      unit: editUnit,
      quantity: editQuantity,
      amount: editAmount,
      inboundDate: editInboundDate,
      operator: editOperator,
      remark: editRemark,
    };

    if (inboundOrders.find((o) => o.id === editItem.id)) {
      setInboundOrders(inboundOrders.map((o) => o.id === editItem.id ? updatedOrder : o));
    } else {
      setInboundOrders([updatedOrder, ...inboundOrders]);
    }
    setEditItem(null);
  };

  const handleApprove = (id: string) => {
    const order = inboundOrders.find((o) => o.id === id);
    if (!order || order.status !== 'pending') return;
    if (!confirm(`确认审核通过入库单 ${order.orderNo}？审核后资产状态将变更为在用，库存将增加。`)) return;

    setInboundOrders(inboundOrders.map((o) =>
      o.id === id ? { ...o, status: 'completed' as const } : o
    ));

    const existingAsset = assetEquipments.find((a) => a.id === order.assetId);
    if (existingAsset) {
      updateAssetEquipment(order.assetId, {
        status: 'in_use',
      });
    } else {
      addAssetEquipment({
        id: order.assetId,
        code: order.assetCode,
        name: order.assetName,
        specification: order.specification,
        unit: order.unit,
        amount: order.amount,
        storageLocation: '',
        status: 'in_use',
        remark: order.remark,
        createTime: order.inboundDate,
      });
    }
  };

  const handleDelete = (id: string) => {
    const order = inboundOrders.find((o) => o.id === id);
    if (!order) return;
    if (!confirm(`确认删除入库单 ${order.orderNo}？`)) return;
    setInboundOrders(inboundOrders.filter((o) => o.id !== id));
  };

  return (
    <div className="p-4">
      <div className="mb-3 flex items-center justify-between">
        <h2 className="text-sm font-semibold text-[#303133]">资产入库管理</h2>
        <PrimaryButton onClick={openAdd}>
          <Plus size={14} /> 新增入库单
        </PrimaryButton>
      </div>

      <div className="grid grid-cols-4 gap-4 mb-4">
        <div className="bg-white rounded shadow-sm border border-[#e4e7ed] p-4">
          <div className="text-xs text-[#606266] mb-1">今日入库单</div>
          <div className="text-2xl font-bold text-[#303133]">{stats.todayCount}</div>
          <div className="text-xs text-[#909399] mt-1">单</div>
        </div>
        <div className="bg-white rounded shadow-sm border border-[#e4e7ed] p-4">
          <div className="text-xs text-[#606266] mb-1">本月入库单</div>
          <div className="text-2xl font-bold text-[#409eff]">{stats.monthCount}</div>
          <div className="text-xs text-[#909399] mt-1">单</div>
        </div>
        <div className="bg-white rounded shadow-sm border border-[#e4e7ed] p-4">
          <div className="text-xs text-[#606266] mb-1">待审核</div>
          <div className="text-2xl font-bold text-[#e6a23c]">{stats.pendingCount}</div>
          <div className="text-xs text-[#909399] mt-1">单</div>
        </div>
        <div className="bg-white rounded shadow-sm border border-[#e4e7ed] p-4">
          <div className="text-xs text-[#606266] mb-1">已完成</div>
          <div className="text-2xl font-bold text-[#67c23a]">{stats.completedCount}</div>
          <div className="text-xs text-[#909399] mt-1">单</div>
        </div>
      </div>

      <SearchBar
        onSearch={() =>
          setApplied({ orderNo: filterOrderNo, assetName: filterAssetName, status: filterStatus, from: filterFrom, to: filterTo })
        }
        onReset={() => {
          setFilterOrderNo('');
          setFilterAssetName('');
          setFilterStatus('');
          setFilterFrom('');
          setFilterTo('');
          setApplied({ orderNo: '', assetName: '', status: '', from: '', to: '' });
        }}
      >
        <SearchField label="入库单号" placeholder="请输入" value={filterOrderNo} onChange={setFilterOrderNo} />
        <SearchField label="资产名称" placeholder="请输入" value={filterAssetName} onChange={setFilterAssetName} />
        <div className="flex items-center gap-2">
          <span className="text-xs text-[#606266] whitespace-nowrap">入库状态：</span>
          <select
            value={filterStatus}
            onChange={(e) => setFilterStatus(e.target.value)}
            className="w-[220px] h-8 px-2 border border-[#dcdfe6] text-xs text-[#303133] bg-white rounded focus:outline-none focus:border-[#2f54eb]"
          >
            <option value="">全部</option>
            <option value="pending">待入库</option>
            <option value="completed">已入库</option>
            <option value="cancelled">已取消</option>
          </select>
        </div>
        <SearchField label="起始日期" type="date" value={filterFrom} onChange={setFilterFrom} />
        <SearchField label="结束日期" type="date" value={filterTo} onChange={setFilterTo} />
      </SearchBar>

      <div className="bg-white rounded shadow-sm border border-[#e4e7ed]">
        <DataTable
          data={filteredData}
          columns={columns}
          rowKey={(row: any) => row.id}
        />
      </div>

      <Modal
        open={!!viewItem}
        title={`资产入库单详情 - ${viewItem?.orderNo}`}
        onClose={() => setViewItem(null)}
        width="max-w-[800px]"
      >
        {viewItem && (
          <div>
            <div className="grid grid-cols-2 gap-x-6 gap-y-2 text-xs mb-4 p-3 border border-[#ebeef5] rounded bg-[#f5f7fa]">
              <div><span className="text-[#606266]">入库单号：</span><span className="text-[#303133]">{viewItem.orderNo}</span></div>
              <div><span className="text-[#606266]">入库状态：</span><span className={statusColor(viewItem.status)}>{statusText(viewItem.status)}</span></div>
              <div><span className="text-[#606266]">资产编码：</span><span className="text-[#303133]">{viewItem.assetCode}</span></div>
              <div><span className="text-[#606266]">资产名称：</span><span className="text-[#303133]">{viewItem.assetName}</span></div>
              <div><span className="text-[#606266]">规格型号：</span><span className="text-[#303133]">{viewItem.specification || '-'}</span></div>
              <div><span className="text-[#606266]">单位：</span><span className="text-[#303133]">{viewItem.unit}</span></div>
              <div><span className="text-[#606266]">数量：</span><span className="text-[#303133]">{viewItem.quantity}</span></div>
              <div><span className="text-[#606266]">金额：</span><span className="text-[#303133]">¥{viewItem.amount.toLocaleString()}</span></div>
              <div><span className="text-[#606266]">入库日期：</span><span className="text-[#303133]">{viewItem.inboundDate}</span></div>
              <div><span className="text-[#606266]">经办人：</span><span className="text-[#303133]">{viewItem.operator}</span></div>
              <div><span className="text-[#606266]">创建时间：</span><span className="text-[#303133]">{viewItem.createTime}</span></div>
              <div className="col-span-2"><span className="text-[#606266]">备注：</span><span className="text-[#303133]">{viewItem.remark || '-'}</span></div>
            </div>
            <div className="flex items-center justify-end gap-2 mt-4 pt-3 border-t border-[#f0f2f5]">
              <DefaultButton onClick={() => setViewItem(null)}>关闭</DefaultButton>
            </div>
          </div>
        )}
      </Modal>

      <Modal
        open={!!editItem}
        title={`${editItem && inboundOrders.find((o) => o.id === editItem.id) ? '编辑' : '新增'}资产入库单`}
        onClose={() => setEditItem(null)}
        width="max-w-[800px]"
      >
        <div className="space-y-4">
          <div>
            <div className="text-xs font-medium text-[#303133] mb-2 border-l-2 border-[#2f54eb] pl-2">基本信息</div>
            <div className="grid grid-cols-2 gap-x-6 gap-y-2 p-3 border border-[#ebeef5] rounded bg-[#fafbfc]">
              <div className="flex items-center gap-2">
                <span className="text-xs text-[#606266] whitespace-nowrap w-20">入库单号：</span>
                <span className="text-xs text-[#303133]">{editItem?.orderNo}</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-xs text-[#606266] whitespace-nowrap w-20">创建时间：</span>
                <span className="text-xs text-[#303133]">{editItem?.createTime}</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-xs text-[#606266] whitespace-nowrap w-20"><span className="text-[#f56c6c]">*</span>资产选择：</span>
                <div className="flex-1 flex items-center gap-2">
                  <input
                    type="text"
                    disabled
                    value={editAssetName || ''}
                    placeholder="请选择资产"
                    className="flex-1 h-8 px-2 border border-[#dcdfe6] text-xs text-[#909399] bg-[#f5f7fa] rounded cursor-not-allowed"
                  />
                  <DefaultButton size="small" onClick={() => setPickerOpen(true)}>
                    选择
                  </DefaultButton>
                </div>
              </div>
              <div className="flex items-center gap-2">
                <span className="text-xs text-[#606266] whitespace-nowrap w-20">规格型号：</span>
                <input
                  type="text"
                  disabled
                  value={editSpecification}
                  className="flex-1 h-8 px-2 border border-[#dcdfe6] text-xs text-[#909399] bg-[#f5f7fa] rounded cursor-not-allowed"
                />
              </div>
              <div className="flex items-center gap-2">
                <span className="text-xs text-[#606266] whitespace-nowrap w-20">单位：</span>
                <input
                  type="text"
                  disabled
                  value={editUnit}
                  className="flex-1 h-8 px-2 border border-[#dcdfe6] text-xs text-[#909399] bg-[#f5f7fa] rounded cursor-not-allowed"
                />
              </div>
              <div className="flex items-center gap-2">
                <span className="text-xs text-[#606266] whitespace-nowrap w-20"><span className="text-[#f56c6c]">*</span>数量：</span>
                <input
                  type="number"
                  value={editQuantity}
                  onChange={(e) => setEditQuantity(Number(e.target.value))}
                  min={1}
                  className="flex-1 h-8 px-2 border border-[#dcdfe6] text-xs text-[#303133] rounded focus:outline-none focus:border-[#2f54eb]"
                />
              </div>
              <div className="flex items-center gap-2">
                <span className="text-xs text-[#606266] whitespace-nowrap w-20">金额：</span>
                <input
                  type="number"
                  value={editAmount}
                  onChange={(e) => setEditAmount(Number(e.target.value))}
                  min={0}
                  className="flex-1 h-8 px-2 border border-[#dcdfe6] text-xs text-[#303133] rounded focus:outline-none focus:border-[#2f54eb]"
                />
              </div>
              <div className="flex items-center gap-2">
                <span className="text-xs text-[#606266] whitespace-nowrap w-20">入库日期：</span>
                <input
                  type="date"
                  value={editInboundDate}
                  onChange={(e) => setEditInboundDate(e.target.value)}
                  className="flex-1 h-8 px-2 border border-[#dcdfe6] text-xs text-[#303133] rounded focus:outline-none focus:border-[#2f54eb]"
                />
              </div>
              <div className="flex items-center gap-2">
                <span className="text-xs text-[#606266] whitespace-nowrap w-20">经办人：</span>
                <input
                  type="text"
                  value={editOperator}
                  onChange={(e) => setEditOperator(e.target.value)}
                  placeholder="请输入经办人"
                  className="flex-1 h-8 px-2 border border-[#dcdfe6] text-xs text-[#303133] rounded focus:outline-none focus:border-[#2f54eb]"
                />
              </div>
              <div className="col-span-2 flex items-start gap-2">
                <span className="text-xs text-[#606266] whitespace-nowrap w-20 pt-1">备注：</span>
                <textarea
                  value={editRemark}
                  onChange={(e) => setEditRemark(e.target.value)}
                  placeholder="请输入备注"
                  rows={2}
                  className="flex-1 px-2 py-1 border border-[#dcdfe6] text-xs text-[#303133] rounded focus:outline-none focus:border-[#2f54eb] resize-none"
                />
              </div>
            </div>
          </div>

          <div className="flex items-center justify-end gap-2 pt-3 border-t border-[#f0f2f5]">
            <DefaultButton onClick={() => setEditItem(null)}>取消</DefaultButton>
            <PrimaryButton onClick={handleSave}>保存</PrimaryButton>
          </div>
        </div>
      </Modal>

      <Modal
        open={pickerOpen}
        title="选择资产"
        onClose={() => setPickerOpen(false)}
        width="max-w-[900px]"
      >
        <div className="space-y-3">
          <div className="flex items-center gap-2 border-b border-[#ebeef5] pb-2">
            <button
              onClick={() => setIsNewAssetMode(false)}
              className={`px-4 py-1.5 text-xs rounded ${!isNewAssetMode ? 'bg-[#2f54eb] text-white' : 'bg-[#f5f7fa] text-[#606266]'}`}
            >
              选择已有资产
            </button>
            <button
              onClick={() => setIsNewAssetMode(true)}
              className={`px-4 py-1.5 text-xs rounded ${isNewAssetMode ? 'bg-[#2f54eb] text-white' : 'bg-[#f5f7fa] text-[#606266]'}`}
            >
              新增资产
            </button>
          </div>

          {!isNewAssetMode && (
          <div className="max-h-[400px] overflow-y-auto border border-[#ebeef5] rounded">
            <table className="w-full text-xs">
              <thead className="bg-[#f5f7fa] sticky top-0">
                <tr className="text-[#606266]">
                  <th className="px-3 py-2 text-left">资产编码</th>
                  <th className="px-3 py-2 text-left">资产名称</th>
                  <th className="px-3 py-2 text-left">规格型号</th>
                  <th className="px-3 py-2 text-left">单位</th>
                  <th className="px-3 py-2 text-right">金额</th>
                  <th className="px-3 py-2 text-center">操作</th>
                </tr>
              </thead>
              <tbody>
                {assetEquipments.map((asset) => (
                  <tr key={asset.id} className="border-t border-[#f0f2f5] hover:bg-[#f5f7fa]">
                    <td className="px-3 py-2 text-[#303133]">{asset.code}</td>
                    <td className="px-3 py-2 text-[#303133]">{asset.name}</td>
                    <td className="px-3 py-2 text-[#303133]">{asset.specification || '-'}</td>
                    <td className="px-3 py-2 text-[#303133]">{asset.unit}</td>
                    <td className="px-3 py-2 text-right text-[#303133]">¥{asset.amount.toLocaleString()}</td>
                    <td className="px-3 py-2 text-center">
                      <TextButton onClick={() => handleSelectAsset(asset)}>选择</TextButton>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          )}

          {isNewAssetMode && (
            <div className="space-y-3 p-3 border border-[#ebeef5] rounded bg-[#fafbfc]">
              <div className="grid grid-cols-2 gap-3">
                <div className="flex items-center gap-2">
                  <span className="text-xs text-[#606266] whitespace-nowrap w-20"><span className="text-[#f56c6c]">*</span>资产名称：</span>
                  <input
                    type="text"
                    value={newAssetName}
                    onChange={(e) => setNewAssetName(e.target.value)}
                    placeholder="请输入资产名称"
                    className="flex-1 h-8 px-2 border border-[#dcdfe6] text-xs text-[#303133] rounded focus:outline-none focus:border-[#2f54eb]"
                  />
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-[#606266] whitespace-nowrap w-20">规格型号：</span>
                  <input
                    type="text"
                    value={newAssetSpecification}
                    onChange={(e) => setNewAssetSpecification(e.target.value)}
                    placeholder="请输入规格型号"
                    className="flex-1 h-8 px-2 border border-[#dcdfe6] text-xs text-[#303133] rounded focus:outline-none focus:border-[#2f54eb]"
                  />
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-[#606266] whitespace-nowrap w-20">计量单位：</span>
                  <input
                    type="text"
                    value={newAssetUnit}
                    onChange={(e) => setNewAssetUnit(e.target.value)}
                    placeholder="如：台、辆"
                    className="flex-1 h-8 px-2 border border-[#dcdfe6] text-xs text-[#303133] rounded focus:outline-none focus:border-[#2f54eb]"
                  />
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-[#606266] whitespace-nowrap w-20">金额：</span>
                  <input
                    type="number"
                    value={newAssetAmount || ''}
                    onChange={(e) => setNewAssetAmount(parseFloat(e.target.value) || 0)}
                    placeholder="0.00"
                    className="flex-1 h-8 px-2 border border-[#dcdfe6] text-xs text-[#303133] rounded focus:outline-none focus:border-[#2f54eb]"
                  />
                </div>
                <div className="flex items-center gap-2 col-span-2">
                  <span className="text-xs text-[#606266] whitespace-nowrap w-20">存放地点：</span>
                  <input
                    type="text"
                    value={newAssetStorageLocation}
                    onChange={(e) => setNewAssetStorageLocation(e.target.value)}
                    placeholder="如：车间A区"
                    className="flex-1 h-8 px-2 border border-[#dcdfe6] text-xs text-[#303133] rounded focus:outline-none focus:border-[#2f54eb]"
                  />
                </div>
                <div className="flex items-start gap-2 col-span-2">
                  <span className="text-xs text-[#606266] whitespace-nowrap w-20 pt-1">备注：</span>
                  <textarea
                    value={newAssetRemark}
                    onChange={(e) => setNewAssetRemark(e.target.value)}
                    placeholder="请输入备注"
                    rows={2}
                    className="flex-1 px-2 py-1 border border-[#dcdfe6] text-xs text-[#303133] rounded focus:outline-none focus:border-[#2f54eb] resize-none"
                  />
                </div>
              </div>
            </div>
          )}

          <div className="flex items-center justify-end gap-2 pt-2">
            <DefaultButton onClick={() => setPickerOpen(false)}>取消</DefaultButton>
            {isNewAssetMode && (
              <PrimaryButton onClick={handleAddNewAsset}>确认新增</PrimaryButton>
            )}
          </div>
        </div>
      </Modal>
    </div>
  );
}
