const buildNodes = (nodes: Array<{ name: string; role: string; approver?: string; desc?: string }>): ApprovalFlowNode[] => {
  return nodes.map((n, i) => ({
    id: 'NODE' + (i + 1) + '_' + Date.now(),
    nodeName: n.name,
    nodeOrder: i + 1,
    approverRole: n.role,
    approverName: n.approver,
    description: n.desc,
    isRequired: true,
  }));
};

