import { useState, useMemo } from 'react';
import { Search, Calculator, FileText } from 'lucide-react';
import { ColumnDef } from '@tanstack/react-table';
import Card, { CardHeader, CardBody } from '@/components/common/Card';
import Button from '@/components/common/Button';
import Input from '@/components/common/Input';
import Select from '@/components/common/Select';
import DataTable from '@/components/common/DataTable';
import Modal from '@/components/common/Modal';
import Badge from '@/components/common/Badge';
import { useStore } from '@/store/useStore';
import { generateId } from '@/utils';
import type { AssetEquipment } from '@/types';

interface DepreciationRecord {
  id: string;
  assetId: string;
  period: string;
  depreciationAmount: number;
  accumulatedDepreciation: number;
  netValue: number;
  createTime: string;
}

interface DepreciationAsset {
  id: string;
  assetCode: string;
  assetName: string;
  originalValue: number;
  usefulYears: number;
  salvageValue: number;
  monthlyDepreciation: number;
  accumulatedDepreciation: number;
  netValue: number;
  status: 'normal' | 'fully_depreciated' | 'scrapped';
  startDate: string;
  records: DepreciationRecord[];
}

const DEFAULT_USEFUL_YEARS = 5;
const SALVAGE_RATE = 0.05;

function calculateMonthsBetween(startDate: string, endDate: Date): number {
  const start = new Date(startDate);
  const years = endDate.getFullYear() - start.getFullYear();
  const months = endDate.getMonth() - start.getMonth();
  return Math.max(0, years * 12 + months);
}

function buildDepreciationAsset(asset: AssetEquipment, recordsMap: Record<string, DepreciationRecord[]>): DepreciationAsset {
  const originalValue = asset.amount;
  const usefulYears = DEFAULT_USEFUL_YEARS;
  const salvageValue = originalValue * SALVAGE_RATE;
  const monthlyDepreciation = (originalValue - salvageValue) / (usefulYears * 12);

  const records = recordsMap[asset.id] || [];
  const manualDepreciation = records.reduce((sum, r) => sum + r.depreciationAmount, 0);

  const now = new Date();
  const elapsedMonths = calculateMonthsBetween(asset.createTime, now);
  const autoDepreciation = Math.min(elapsedMonths * monthlyDepreciation, originalValue - salvageValue);

  const accumulatedDepreciation = Math.min(autoDepreciation + manualDepreciation, originalValue - salvageValue);
  const netValue = originalValue - accumulatedDepreciation;

  let status: 'normal' | 'fully_depreciated' | 'scrapped';
  if (asset.status === 'scrapped' || asset.status === 'written_off') {
    status = 'scrapped';
  } else if (netValue <= salvageValue + 0.01) {
    status = 'fully_depreciated';
  } else {
    status = 'normal';
  }

  return {
    id: asset.id,
    assetCode: asset.code,
    assetName: asset.name,
    originalValue,
    usefulYears,
    salvageValue,
    monthlyDepreciation,
    accumulatedDepreciation,
    netValue,
    status,
    startDate: asset.createTime,
    records,
  };
}

export default function AssetDepreciation() {
  const { assetEquipments } = useStore();
  const [depreciationRecords, setDepreciationRecords] = useState<Record<string, DepreciationRecord[]>>({});
  const [codeFilter, setCodeFilter] = useState('');
  const [nameFilter, setNameFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [detailModalOpen, setDetailModalOpen] = useState(false);
  const [viewingAsset, setViewingAsset] = useState<DepreciationAsset | null>(null);
  const [isCalculating, setIsCalculating] = useState(false);

  const assets = useMemo(() => {
    return assetEquipments.map(asset => buildDepreciationAsset(asset, depreciationRecords));
  }, [assetEquipments, depreciationRecords]);

  const stats = useMemo(() => {
    const totalAssets = assets.length;
    const totalOriginalValue = assets.reduce((sum, a) => sum + a.originalValue, 0);
    const totalAccumulatedDepreciation = assets.reduce((sum, a) => sum + a.accumulatedDepreciation, 0);
    const totalNetValue = totalOriginalValue - totalAccumulatedDepreciation;

    const monthlyDepreciation = assets
      .filter(a => a.status === 'normal')
      .reduce((sum, a) => sum + a.monthlyDepreciation, 0);

    return {
      totalAssets,
      monthlyDepreciation,
      totalAccumulatedDepreciation,
      totalNetValue,
    };
  }, [assets]);

  const filteredData = assets
    .filter(a => !codeFilter || a.assetCode.toLowerCase().includes(codeFilter.toLowerCase()))
    .filter(a => !nameFilter || a.assetName.toLowerCase().includes(nameFilter.toLowerCase()))
    .filter(a => !statusFilter || a.status === statusFilter);

  const statusOptions = [
    { value: '', label: '全部状态' },
    { value: 'normal', label: '正常折旧' },
    { value: 'fully_depreciated', label: '已提足' },
    { value: 'scrapped', label: '已报废' },
  ];

  const statusBadgeVariants: Record<string, 'default' | 'success' | 'danger' | 'warning' | 'info'> = {
    normal: 'success',
    fully_depreciated: 'warning',
    scrapped: 'danger',
  };

  const statusLabels: Record<string, string> = {
    normal: '正常折旧',
    fully_depreciated: '已提足',
    scrapped: '已报废',
  };

  const handleView = (asset: DepreciationAsset) => {
    setViewingAsset(asset);
    setDetailModalOpen(true);
  };

  const handleCalculateDepreciation = () => {
    if (!window.confirm('确认计提本月折旧吗？将对所有正常折旧状态的资产计提本月折旧。')) {
      return;
    }

    setIsCalculating(true);

    const now = new Date();
    const period = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
    const createTime = now.toISOString().slice(0, 10);

    setTimeout(() => {
      setDepreciationRecords(prev => {
        const next: Record<string, DepreciationRecord[]> = { ...prev };

        assets.forEach(asset => {
          if (asset.status !== 'normal') return;

          const currentRecords = next[asset.id] || [];
          const alreadyExists = currentRecords.some(r => r.period === period);
          if (alreadyExists) return;

          const totalAccumulated = asset.accumulatedDepreciation + asset.monthlyDepreciation;
          const newNetValue = Math.max(asset.originalValue - totalAccumulated, asset.salvageValue);
          const actualDepreciation = asset.originalValue - asset.accumulatedDepreciation - newNetValue;

          const newRecord: DepreciationRecord = {
            id: generateId(),
            assetId: asset.id,
            period,
            depreciationAmount: actualDepreciation,
            accumulatedDepreciation: asset.accumulatedDepreciation + actualDepreciation,
            netValue: newNetValue,
            createTime,
          };

          next[asset.id] = [newRecord, ...currentRecords];
        });

        return next;
      });

      setIsCalculating(false);
      window.alert('本月折旧计提完成！');
    }, 1000);
  };

  const columns: ColumnDef<DepreciationAsset, unknown>[] = [
    { accessorKey: 'assetCode', header: '资产编码' },
    { accessorKey: 'assetName', header: '资产名称' },
    {
      accessorKey: 'originalValue',
      header: '原值',
      cell: ({ row }) => `¥${row.original.originalValue.toLocaleString()}`,
    },
    {
      accessorKey: 'usefulYears',
      header: '使用年限',
      cell: ({ row }) => `${row.original.usefulYears}年`,
    },
    {
      accessorKey: 'accumulatedDepreciation',
      header: '已提折旧',
      cell: ({ row }) => `¥${row.original.accumulatedDepreciation.toLocaleString()}`,
    },
    {
      accessorKey: 'monthlyDepreciation',
      header: '本月折旧',
      cell: ({ row }) => (
        <span className={row.original.status === 'normal' ? 'text-blue-600 font-medium' : 'text-slate-400'}>
          ¥{row.original.monthlyDepreciation.toFixed(2)}
        </span>
      ),
    },
    {
      accessorKey: 'netValue',
      header: '净值',
      cell: ({ row }) => (
        <span className="font-medium">¥{row.original.netValue.toLocaleString()}</span>
      ),
    },
    {
      accessorKey: 'status',
      header: '折旧状态',
      cell: ({ row }) => (
        <Badge variant={statusBadgeVariants[row.original.status]}>
          {statusLabels[row.original.status]}
        </Badge>
      ),
    },
    {
      id: 'actions',
      header: '操作',
      cell: ({ row }) => (
        <div className="flex items-center gap-2 flex-wrap">
          <Button variant="ghost" size="sm" onClick={() => handleView(row.original)}>
            <FileText size={14} /> 折旧明细
          </Button>
        </div>
      ),
    },
  ];

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-900">折旧管理</h1>
        <Button onClick={handleCalculateDepreciation} disabled={isCalculating}>
          <Calculator size={16} />
          {isCalculating ? '计提中...' : '计提本月折旧'}
        </Button>
      </div>

      <div className="grid grid-cols-4 gap-4">
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">资产总数</div>
            <div className="text-2xl font-bold text-slate-900">{stats.totalAssets}</div>
            <div className="text-xs text-slate-400 mt-1">台/套</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">本月折旧额</div>
            <div className="text-2xl font-bold text-blue-600">¥{stats.monthlyDepreciation.toFixed(2)}</div>
            <div className="text-xs text-slate-400 mt-1">月折旧</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">累计折旧额</div>
            <div className="text-2xl font-bold text-amber-600">¥{stats.totalAccumulatedDepreciation.toLocaleString()}</div>
            <div className="text-xs text-slate-400 mt-1">累计</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">资产净值</div>
            <div className="text-2xl font-bold text-green-600">¥{stats.totalNetValue.toLocaleString()}</div>
            <div className="text-xs text-slate-400 mt-1">净值总额</div>
          </CardBody>
        </Card>
      </div>

      <Card>
        <CardBody>
          <div className="flex items-center gap-4">
            <div className="flex-shrink-0 w-12 h-12 bg-blue-50 rounded-lg flex items-center justify-center">
              <Calculator size={24} className="text-blue-600" />
            </div>
            <div>
              <div className="text-sm font-medium text-slate-900">折旧方法：平均年限法</div>
              <div className="text-xs text-slate-500 mt-1">
                月折旧额 = (原值 - 残值) / (使用年限 × 12)，残值率默认为 5%
              </div>
            </div>
          </div>
        </CardBody>
      </Card>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-4 flex-wrap">
            <div className="relative">
              <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input
                placeholder="资产编码..."
                value={codeFilter}
                onChange={(e) => setCodeFilter(e.target.value)}
                className="pl-9 w-48"
              />
            </div>
            <div className="relative">
              <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input
                placeholder="资产名称..."
                value={nameFilter}
                onChange={(e) => setNameFilter(e.target.value)}
                className="pl-9 w-48"
              />
            </div>
            <Select
              options={statusOptions}
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              placeholder="全部状态"
              className="w-36"
            />
          </div>
        </CardHeader>
        <CardBody>
          <DataTable data={filteredData} columns={columns} pageSize={10} />
        </CardBody>
      </Card>

      <Modal
        open={detailModalOpen}
        onClose={() => setDetailModalOpen(false)}
        title="折旧明细"
        size="lg"
      >
        {viewingAsset && (
          <div className="space-y-4 min-w-[700px]">
            <div className="grid grid-cols-4 gap-4 text-sm p-4 bg-slate-50 rounded-lg">
              <div>
                <span className="text-slate-500">资产编码：</span>
                <span className="font-medium">{viewingAsset.assetCode}</span>
              </div>
              <div>
                <span className="text-slate-500">资产名称：</span>
                <span className="font-medium">{viewingAsset.assetName}</span>
              </div>
              <div>
                <span className="text-slate-500">状态：</span>
                <Badge variant={statusBadgeVariants[viewingAsset.status]}>
                  {statusLabels[viewingAsset.status]}
                </Badge>
              </div>
              <div>
                <span className="text-slate-500">原值：</span>
                <span className="font-medium">¥{viewingAsset.originalValue.toLocaleString()}</span>
              </div>
              <div>
                <span className="text-slate-500">使用年限：</span>
                <span className="font-medium">{viewingAsset.usefulYears}年</span>
              </div>
              <div>
                <span className="text-slate-500">残值：</span>
                <span className="font-medium">¥{viewingAsset.salvageValue.toLocaleString()}</span>
              </div>
              <div>
                <span className="text-slate-500">月折旧额：</span>
                <span className="font-medium text-blue-600">¥{viewingAsset.monthlyDepreciation.toFixed(2)}</span>
              </div>
              <div>
                <span className="text-slate-500">累计折旧：</span>
                <span className="font-medium">¥{viewingAsset.accumulatedDepreciation.toLocaleString()}</span>
              </div>
              <div>
                <span className="text-slate-500">净值：</span>
                <span className="font-medium text-green-600">¥{viewingAsset.netValue.toLocaleString()}</span>
              </div>
              <div>
                <span className="text-slate-500">开始折旧：</span>
                <span className="font-medium">{viewingAsset.startDate}</span>
              </div>
              <div>
                <span className="text-slate-500">折旧方法：</span>
                <span className="font-medium">平均年限法</span>
              </div>
            </div>

            <div>
              <div className="text-sm font-medium text-slate-900 mb-3">折旧历史记录</div>
              {viewingAsset.records.length > 0 ? (
                <div className="border border-slate-200 rounded-lg overflow-hidden">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="bg-slate-50 text-slate-600">
                        <th className="px-4 py-3 text-left font-medium">期间</th>
                        <th className="px-4 py-3 text-right font-medium">本月折旧</th>
                        <th className="px-4 py-3 text-right font-medium">累计折旧</th>
                        <th className="px-4 py-3 text-right font-medium">净值</th>
                        <th className="px-4 py-3 text-center font-medium">计提日期</th>
                      </tr>
                    </thead>
                    <tbody>
                      {viewingAsset.records.map((record) => (
                        <tr key={record.id} className="border-t border-slate-100 hover:bg-slate-50">
                          <td className="px-4 py-3 font-medium">{record.period}</td>
                          <td className="px-4 py-3 text-right text-blue-600">
                            ¥{record.depreciationAmount.toFixed(2)}
                          </td>
                          <td className="px-4 py-3 text-right">
                            ¥{record.accumulatedDepreciation.toFixed(2)}
                          </td>
                          <td className="px-4 py-3 text-right text-green-600 font-medium">
                            ¥{record.netValue.toFixed(2)}
                          </td>
                          <td className="px-4 py-3 text-center text-slate-500">
                            {record.createTime}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              ) : (
                <div className="py-12 text-center text-slate-400 border border-dashed border-slate-200 rounded-lg">
                  暂无折旧记录
                </div>
              )}
            </div>

            <div className="flex justify-end gap-3 pt-2">
              <Button variant="secondary" onClick={() => setDetailModalOpen(false)}>
                关闭
              </Button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}
