import { useState, useMemo } from 'react';
import { Plus, Search, Eye, Check, X } from 'lucide-react';
import { ColumnDef } from '@tanstack/react-table';
import Card, { CardHeader, CardBody } from '@/components/common/Card';
import Button from '@/components/common/Button';
import Input from '@/components/common/Input';
import Select from '@/components/common/Select';
import DataTable from '@/components/common/DataTable';
import Modal from '@/components/common/Modal';
import Badge from '@/components/common/Badge';
import { generateId } from '@/utils';
import { useStore } from '@/store/useStore';

type RequisitionStatus = 'pending' | 'approved' | 'returned' | 'cancelled';

interface AssetRequisition {
  id: string;
  requisitionNo: string;
  assetId: string;
  assetName: string;
  specification: string;
  unit: string;
  quantity: number;
  applicant: string;
  department: string;
  expectedReturnDate: string;
  status: RequisitionStatus;
  requisitionDate: string;
  purpose: string;
  remark: string;
  approver?: string;
  approveTime?: string;
}

const mockRequisitions: AssetRequisition[] = [
  {
    id: '1',
    requisitionNo: 'LZ20240601001',
    assetId: 'AE001',
    assetName: '数控车床',
    specification: 'CJK6136',
    unit: '台',
    quantity: 1,
    applicant: '张三',
    department: '展览部',
    expectedReturnDate: '2024-06-15',
    status: 'pending',
    requisitionDate: '2024-06-01',
    purpose: '展会现场使用',
    remark: '需提前一天调试',
  },
  {
    id: '2',
    requisitionNo: 'LZ20240602002',
    assetId: 'AE002',
    assetName: '铣床',
    specification: 'X5032',
    unit: '台',
    quantity: 1,
    applicant: '李四',
    department: '市场部',
    expectedReturnDate: '2024-06-20',
    status: 'approved',
    requisitionDate: '2024-06-02',
    purpose: '客户演示用',
    remark: '',
  },
  {
    id: '3',
    requisitionNo: 'LZ20240603003',
    assetId: 'AE003',
    assetName: '激光切割机',
    specification: 'LCT-3015',
    unit: '台',
    quantity: 1,
    applicant: '王五',
    department: '宣传部',
    expectedReturnDate: '2024-06-10',
    status: 'returned',
    requisitionDate: '2024-06-03',
    purpose: '活动拍摄',
    remark: '已归还，设备完好',
  },
  {
    id: '4',
    requisitionNo: 'LZ20240605004',
    assetId: 'AE004',
    assetName: '空压机',
    specification: 'GA37',
    unit: '台',
    quantity: 1,
    applicant: '赵六',
    department: '活动部',
    expectedReturnDate: '2024-06-12',
    status: 'cancelled',
    requisitionDate: '2024-06-05',
    purpose: '新品发布会',
    remark: '活动取消',
  },
  {
    id: '5',
    requisitionNo: 'LZ20240610005',
    assetId: 'AE005',
    assetName: '叉车',
    specification: 'CPCD30',
    unit: '辆',
    quantity: 1,
    applicant: '孙七',
    department: '展览部',
    expectedReturnDate: '2024-06-25',
    status: 'approved',
    requisitionDate: '2024-06-10',
    purpose: '展会现场通讯',
    remark: '',
  },
];

const statusOptions = [
  { value: '', label: '全部状态' },
  { value: 'pending', label: '待审核' },
  { value: 'approved', label: '领用中' },
  { value: 'returned', label: '已归还' },
  { value: 'cancelled', label: '已取消' },
];

const statusLabels: Record<RequisitionStatus, string> = {
  pending: '待审核',
  approved: '领用中',
  returned: '已归还',
  cancelled: '已取消',
};

const statusVariants: Record<RequisitionStatus, 'default' | 'success' | 'danger' | 'warning'> = {
  pending: 'warning',
  approved: 'success',
  returned: 'default',
  cancelled: 'danger',
};

const departments = ['展览部', '市场部', '宣传部', '活动部', '行政部', '技术部'];

export default function AssetRequisition() {
  const { employees, assetEquipments, updateAssetEquipment } = useStore();
  const [requisitions, setRequisitions] = useState<AssetRequisition[]>(mockRequisitions);
  const [requisitionNoFilter, setRequisitionNoFilter] = useState('');
  const [assetNameFilter, setAssetNameFilter] = useState('');
  const [applicantFilter, setApplicantFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [modalOpen, setModalOpen] = useState(false);
  const [detailModalOpen, setDetailModalOpen] = useState(false);
  const [viewingRecord, setViewingRecord] = useState<AssetRequisition | null>(null);
  const [editingRecord, setEditingRecord] = useState<AssetRequisition | null>(null);

  const [formData, setFormData] = useState({
    assetId: '',
    assetName: '',
    specification: '',
    unit: '',
    quantity: 1,
    applicant: '',
    department: '',
    expectedReturnDate: '',
    purpose: '',
    remark: '',
  });

  const stats = useMemo(() => {
    const today = new Date().toISOString().slice(0, 10);
    const thisMonth = today.slice(0, 7);
    const todayCount = requisitions.filter(r => r.requisitionDate === today).length;
    const monthCount = requisitions.filter(r => r.requisitionDate.startsWith(thisMonth)).length;
    const pendingCount = requisitions.filter(r => r.status === 'pending').length;
    const approvedCount = requisitions.filter(r => r.status === 'approved').length;
    return { todayCount, monthCount, pendingCount, approvedCount };
  }, [requisitions]);

  const filteredData = requisitions
    .filter(r => !requisitionNoFilter || r.requisitionNo.toLowerCase().includes(requisitionNoFilter.toLowerCase()))
    .filter(r => !assetNameFilter || r.assetName.toLowerCase().includes(assetNameFilter.toLowerCase()))
    .filter(r => !applicantFilter || r.applicant.toLowerCase().includes(applicantFilter.toLowerCase()))
    .filter(r => !statusFilter || r.status === statusFilter)
    .filter(r => {
      const matchStart = !dateRange.start || r.requisitionDate >= dateRange.start;
      const matchEnd = !dateRange.end || r.requisitionDate <= dateRange.end;
      return matchStart && matchEnd;
    });

  const columns: ColumnDef<AssetRequisition, unknown>[] = [
    { accessorKey: 'requisitionNo', header: '领用单号' },
    { accessorKey: 'assetName', header: '资产名称' },
    { accessorKey: 'specification', header: '规格型号' },
    {
      accessorKey: 'quantity',
      header: '数量',
      cell: ({ row }) => `${row.original.quantity} ${row.original.unit}`,
    },
    { accessorKey: 'applicant', header: '领用人' },
    { accessorKey: 'department', header: '领用部门' },
    { accessorKey: 'expectedReturnDate', header: '预计归还日期' },
    {
      accessorKey: 'status',
      header: '状态',
      cell: ({ row }) => (
        <Badge variant={statusVariants[row.original.status]}>
          {statusLabels[row.original.status]}
        </Badge>
      ),
    },
    { accessorKey: 'requisitionDate', header: '领用日期' },
    {
      id: 'actions',
      header: '操作',
      cell: ({ row }) => (
        <div className="flex items-center gap-2 flex-wrap">
          <Button variant="ghost" size="sm" onClick={() => handleView(row.original)}>查看</Button>
          {row.original.status === 'pending' && (
            <>
              <Button variant="ghost" size="sm" onClick={() => handleApprove(row.original)}>
                <Check size={14} className="text-green-600" />
                <span className="text-green-600">审核</span>
              </Button>
              <Button variant="ghost" size="sm" onClick={() => handleReject(row.original)}>
                <X size={14} className="text-red-500" />
                <span className="text-red-500">驳回</span>
              </Button>
            </>
          )}
        </div>
      ),
    },
  ];

  const assetOptions = assetEquipments.filter(a => a.status === 'in_use').map(a => ({ value: a.id, label: a.name }));
  const employeeOptions = employees.filter(e => e.status === 'enabled').map(e => ({ value: e.name, label: e.name }));
  const departmentOptions = departments.map(d => ({ value: d, label: d }));

  const generateRequisitionNo = () => {
    const date = new Date();
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    const count = requisitions.length + 1;
    return `LZ${year}${month}${day}${String(count).padStart(3, '0')}`;
  };

  const handleOpenModal = () => {
    setEditingRecord(null);
    setFormData({
      assetId: '',
      assetName: '',
      specification: '',
      unit: '',
      quantity: 1,
      applicant: '',
      department: '',
      expectedReturnDate: '',
      purpose: '',
      remark: '',
    });
    setModalOpen(true);
  };

  const handleView = (record: AssetRequisition) => {
    setViewingRecord(record);
    setDetailModalOpen(true);
  };

  const handleAssetChange = (assetId: string) => {
    const asset = assetEquipments.find(a => a.id === assetId);
    if (asset) {
      setFormData({
        ...formData,
        assetId: asset.id,
        assetName: asset.name,
        specification: asset.specification || '',
        unit: asset.unit,
      });
    } else {
      setFormData({
        ...formData,
        assetId: '',
        assetName: '',
        specification: '',
        unit: '',
      });
    }
  };

  const handleSubmit = () => {
    if (!formData.assetId) {
      alert('请选择资产');
      return;
    }
    if (!formData.applicant) {
      alert('请填写领用人');
      return;
    }
    if (!formData.department) {
      alert('请选择领用部门');
      return;
    }
    if (!formData.quantity || formData.quantity <= 0) {
      alert('请填写正确的领用数量');
      return;
    }
    if (!formData.expectedReturnDate) {
      alert('请选择预计归还日期');
      return;
    }

    const newRecord: AssetRequisition = {
      id: generateId(),
      requisitionNo: generateRequisitionNo(),
      assetId: formData.assetId,
      assetName: formData.assetName,
      specification: formData.specification,
      unit: formData.unit,
      quantity: formData.quantity,
      applicant: formData.applicant,
      department: formData.department,
      expectedReturnDate: formData.expectedReturnDate,
      status: 'pending',
      requisitionDate: new Date().toISOString().slice(0, 10),
      purpose: formData.purpose,
      remark: formData.remark,
    };

    setRequisitions([newRecord, ...requisitions]);
    setModalOpen(false);
  };

  const handleApprove = (record: AssetRequisition) => {
    if (confirm(`确认通过领用申请"${record.requisitionNo}"吗？`)) {
      setRequisitions(requisitions.map(r =>
        r.id === record.id
          ? { ...r, status: 'approved', approver: '管理员', approveTime: new Date().toISOString().slice(0, 10) }
          : r
      ));
      updateAssetEquipment(record.assetId, { status: 'in_requisition' });
    }
  };

  const handleReject = (record: AssetRequisition) => {
    if (confirm(`确认驳回领用申请"${record.requisitionNo}"吗？`)) {
      setRequisitions(requisitions.map(r =>
        r.id === record.id ? { ...r, status: 'cancelled' } : r
      ));
      if (record.status === 'approved') {
        updateAssetEquipment(record.assetId, { status: 'in_use' });
      }
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-900">资产领用管理</h1>
        <Button onClick={handleOpenModal}>
          <Plus size={16} />
          新增领用
        </Button>
      </div>

      <div className="grid grid-cols-4 gap-4">
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">今日领用</div>
            <div className="text-2xl font-bold text-slate-900">{stats.todayCount}</div>
            <div className="text-xs text-slate-400 mt-1">笔</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">本月领用</div>
            <div className="text-2xl font-bold text-blue-600">{stats.monthCount}</div>
            <div className="text-xs text-slate-400 mt-1">笔</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">待审核</div>
            <div className="text-2xl font-bold text-orange-600">{stats.pendingCount}</div>
            <div className="text-xs text-slate-400 mt-1">笔</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">领用中</div>
            <div className="text-2xl font-bold text-green-600">{stats.approvedCount}</div>
            <div className="text-xs text-slate-400 mt-1">笔</div>
          </CardBody>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-4 flex-wrap">
            <div className="relative">
              <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input
                placeholder="领用单号..."
                value={requisitionNoFilter}
                onChange={(e) => setRequisitionNoFilter(e.target.value)}
                className="pl-9 w-48"
              />
            </div>
            <div className="relative">
              <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input
                placeholder="资产名称..."
                value={assetNameFilter}
                onChange={(e) => setAssetNameFilter(e.target.value)}
                className="pl-9 w-48"
              />
            </div>
            <div className="relative">
              <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input
                placeholder="领用人..."
                value={applicantFilter}
                onChange={(e) => setApplicantFilter(e.target.value)}
                className="pl-9 w-40"
              />
            </div>
            <Select
              options={statusOptions}
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              placeholder="全部状态"
            />
            <Input
              type="date"
              value={dateRange.start}
              onChange={(e) => setDateRange({ ...dateRange, start: e.target.value })}
              className="w-40"
            />
            <span className="text-slate-500">至</span>
            <Input
              type="date"
              value={dateRange.end}
              onChange={(e) => setDateRange({ ...dateRange, end: e.target.value })}
              className="w-40"
            />
          </div>
        </CardHeader>
        <CardBody>
          <DataTable data={filteredData} columns={columns} pageSize={10} />
        </CardBody>
      </Card>

      <Modal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        title="新增资产领用"
        size="lg"
      >
        <div className="space-y-4 min-w-[600px]">
          <div className="grid grid-cols-2 gap-4">
            <Select
              label="选择资产"
              options={assetOptions}
              value={formData.assetId}
              onChange={(e) => handleAssetChange(e.target.value)}
              placeholder="请选择资产"
            />
            <Input
              label="规格型号"
              value={formData.specification}
              disabled
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <Select
              label="领用人"
              options={employeeOptions}
              value={formData.applicant}
              onChange={(e) => setFormData({ ...formData, applicant: e.target.value })}
              placeholder="请选择领用人"
            />
            <Select
              label="领用部门"
              options={departmentOptions}
              value={formData.department}
              onChange={(e) => setFormData({ ...formData, department: e.target.value })}
              placeholder="请选择部门"
            />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <Input
              label="领用数量"
              type="number"
              min={1}
              value={formData.quantity || ''}
              onChange={(e) => setFormData({ ...formData, quantity: parseInt(e.target.value) || 0 })}
            />
            <Input
              label="预计归还日期"
              type="date"
              value={formData.expectedReturnDate}
              onChange={(e) => setFormData({ ...formData, expectedReturnDate: e.target.value })}
            />
          </div>
          <Input
            label="用途"
            value={formData.purpose}
            onChange={(e) => setFormData({ ...formData, purpose: e.target.value })}
            placeholder="请输入领用用途"
          />
          <Input
            label="备注"
            value={formData.remark}
            onChange={(e) => setFormData({ ...formData, remark: e.target.value })}
            placeholder="备注信息"
          />
          <div className="flex justify-end gap-3 pt-2">
            <Button variant="secondary" onClick={() => setModalOpen(false)}>
              取消
            </Button>
            <Button onClick={handleSubmit}>
              提交申请
            </Button>
          </div>
        </div>
      </Modal>

      <Modal
        open={detailModalOpen}
        onClose={() => setDetailModalOpen(false)}
        title="领用详情"
        size="lg"
      >
        {viewingRecord && (
          <div className="space-y-4 min-w-[600px]">
            <div className="grid grid-cols-2 gap-4 text-sm">
              <div><span className="text-slate-500">领用单号：</span>{viewingRecord.requisitionNo}</div>
              <div><span className="text-slate-500">状态：</span>
                <Badge variant={statusVariants[viewingRecord.status]}>
                  {statusLabels[viewingRecord.status]}
                </Badge>
              </div>
              <div><span className="text-slate-500">资产名称：</span>{viewingRecord.assetName}</div>
              <div><span className="text-slate-500">规格型号：</span>{viewingRecord.specification}</div>
              <div><span className="text-slate-500">数量：</span>{viewingRecord.quantity} {viewingRecord.unit}</div>
              <div><span className="text-slate-500">领用人：</span>{viewingRecord.applicant}</div>
              <div><span className="text-slate-500">领用部门：</span>{viewingRecord.department}</div>
              <div><span className="text-slate-500">领用日期：</span>{viewingRecord.requisitionDate}</div>
              <div><span className="text-slate-500">预计归还日期：</span>{viewingRecord.expectedReturnDate}</div>
              <div><span className="text-slate-500">用途：</span>{viewingRecord.purpose || '-'}</div>
              {viewingRecord.approver && (
                <div><span className="text-slate-500">审核人：</span>{viewingRecord.approver}</div>
              )}
              {viewingRecord.approveTime && (
                <div><span className="text-slate-500">审核时间：</span>{viewingRecord.approveTime}</div>
              )}
              <div className="col-span-2"><span className="text-slate-500">备注：</span>{viewingRecord.remark || '-'}</div>
            </div>
            <div className="flex justify-end pt-2">
              <Button variant="secondary" onClick={() => setDetailModalOpen(false)}>
                关闭
              </Button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}
