export default function Sidebar() {
  const [expandedMenus, setExpandedMenus] = useState<string[]>(['库存管理']);

  const toggleMenu = (title: string) => {
    setExpandedMenus((prev) =>
      prev.includes(title) ? prev.filter((t) => t !== title) : [...prev, title]
    );
  };

  const renderSubMenu = (child: MenuChild, depth: number = 2) => {
    const hasChildren = child.children && child.children.length > 0;
    const paddingLeft = depth === 2 ? 'pl-12' : 'pl-16';

    if (hasChildren) {
      return (
        <div key={child.path}>
          <button
            onClick={() => toggleMenu(child.title)}
            className={`w-full flex items-center gap-3 ${paddingLeft} pr-4 py-2 text-sm hover:bg-[#1f3a5f] hover:text-white transition-colors`}
          >
            <span className="w-1 h-1 rounded-full bg-current opacity-40"></span>
            <span className="flex-1 text-left">{child.title}</span>
            <ChevronRight
              size={14}
              className={`transition-transform ${
                expandedMenus.includes(child.title) ? 'rotate-90' : ''
              }`}
            />
          </button>
          {expandedMenus.includes(child.title) && (
            <div className="bg-[#000810]">
              {child.children!.filter(c => c.visible !== false).map((c) => (
              <NavLink
                key={c.path}
                to={c.path}
                className={({ isActive }) =>
                  `flex items-center gap-3 pl-20 pr-4 py-2 text-sm transition-colors ${
                    isActive
                      ? 'bg-[#2f54eb] text-white'
                      : 'text-[#c8d3e0] hover:bg-[#1f3a5f] hover:text-white'
                  }`
                }
              >
                <span className="w-1 h-1 rounded-full bg-current opacity-40"></span>
                <span>{c.title}</span>
              </NavLink>
            ))}
            </div>
          )}
        </div>
      );
    }

    return (
      <NavLink
        key={child.path}
        to={child.path}
        className={({ isActive }) =>
          `flex items-center gap-3 ${paddingLeft} pr-4 py-2 text-sm transition-colors ${
            isActive
              ? 'bg-[#2f54eb] text-white'
              : 'text-[#c8d3e0] hover:bg-[#1f3a5f] hover:text-white'
          }`
        }
      >
        <span className="w-1 h-1 rounded-full bg-current opacity-40"></span>
        <span>{child.title}</span>
      </NavLink>
    );
  };

  return (
    <aside className="fixed top-[56px] left-0 bottom-0 w-[208px] bg-[#001529] text-[#c8d3e0] overflow-y-auto z-40">
      <nav className="py-1">
        {menuItems.map((item) => (
          <div key={item.title}>
            {item.children ? (
              <>
                <button
                  onClick={() => toggleMenu(item.title)}
                  className="w-full flex items-center gap-3 px-4 py-2.5 text-sm hover:bg-[#1f3a5f] hover:text-white transition-colors"
                >
                  <item.icon size={16} className="text-[#6b9fd4]" />
                  <span className="flex-1 text-left">{item.title}</span>
                  <ChevronRight
                    size={14}
                    className={`transition-transform ${
                      expandedMenus.includes(item.title) ? 'rotate-90' : ''
                    }`}
                  />
                </button>
                {expandedMenus.includes(item.title) && (
                  <div className="bg-[#000c17]">
                    {item.children
                      .filter(child => child.visible !== false)
                      .map((child) => renderSubMenu(child))
                    }
                  </div>
                )}
              </>
            ) : (
              <NavLink
                to={item.path || ''}
                className={({ isActive }) =>
                  `flex items-center gap-3 px-4 py-2.5 text-sm transition-colors ${
                    isActive ? 'bg-[#2f54eb] text-white' : 'hover:bg-[#1f3a5f] hover:text-white'
                  }`
                }
              >
                <item.icon size={16} />
                <span>{item.title}</span>
              </NavLink>
            )}
          </div>
        ))}
      </nav>
    </aside>
  );
}
