import { useState, useMemo } from 'react';
import { Download, FileText, Calendar, MapPin, User } from 'lucide-react';
import { ColumnDef } from '@tanstack/react-table';
import Card, { CardHeader, CardBody } from '@/components/common/Card';
import Button from '@/components/common/Button';
import Input from '@/components/common/Input';
import Select from '@/components/common/Select';
import DataTable from '@/components/common/DataTable';
import Badge from '@/components/common/Badge';
import Modal from '@/components/common/Modal';
import { useStore } from '@/store/useStore';
import * as XLSX from 'xlsx';

const projectStatusMap: Record<string, { label: string; variant: 'default' | 'warning' | 'success' | 'danger' }> = {
  planning: { label: '筹备中', variant: 'default' },
  preparing: { label: '准备中', variant: 'warning' },
  ongoing: { label: '进行中', variant: 'success' },
  completed: { label: '已结束', variant: 'default' },
};

const orderTypeMap: Record<string, string> = {
  requisition: '领料单',
  production: '领料单',
  workorder: '工单',
  scrap: '报废单',
};

export default function ExhibitionRequisitionReport() {
  const { outboundOrders, exhibitionProjects, products, categories } = useStore();
  const [dateRange, setDateRange] = useState({ start: '', end: '' });
  const [projectFilter, setProjectFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [selectedProject, setSelectedProject] = useState<typeof exhibitionProjects[0] | null>(null);

  // 以项目为维度汇总数据
  const reportData = useMemo(() => {
    const result = exhibitionProjects
      .map(project => {
        // 过滤该项目下的出库单
        const projectOrders = outboundOrders.filter(o => o.projectId === project.id);
        const submittedOrders = projectOrders.filter(o => o.status === 'submitted');

        // 区分订单类型：工单(workorder)和其他领料单(requisition/production)
        const workOrders = submittedOrders.filter(o => o.type === 'workorder');
        const requisitionOrders = submittedOrders.filter(o =>
          o.type === 'requisition' || o.type === 'production'
        );

        // 理论领料数量 = 领料单出库数量
        const theoryQuantity = requisitionOrders.reduce((sum, o) =>
          sum + o.details.reduce((s, d) => s + d.quantity, 0), 0
        );

        // 实际领料数量 = 工单实际使用数量（这里简化为工单数量，实际场景可能从工单详情获取）
        const actualQuantity = workOrders.reduce((sum, o) =>
          sum + o.details.reduce((s, d) => s + d.quantity, 0), 0
        );

        // 涉及的物料种类
        const allProducts = new Set<string>();
        submittedOrders.forEach(o => {
          o.details.forEach(d => {
            if (d.productId) allProducts.add(d.productId);
          });
        });

        return {
          project,
          orderCount: projectOrders.length,
          workOrderCount: workOrders.length,
          requisitionCount: requisitionOrders.length,
          theoryQuantity,
          actualQuantity,
          productCount: allProducts.size,
          orders: submittedOrders,
        };
      })
      .filter(item => {
        const matchProject = !projectFilter || item.project.id === projectFilter;
        const matchStatus = !statusFilter || item.project.status === statusFilter;
        const matchDate = (!dateRange.start || item.project.startDate >= dateRange.start) &&
          (!dateRange.end || item.project.endDate <= dateRange.end);
        return matchProject && matchStatus && matchDate;
      });

    return result;
  }, [exhibitionProjects, outboundOrders, projectFilter, statusFilter, dateRange]);

  const totalOrders = reportData.reduce((sum, d) => sum + d.orderCount, 0);
  const totalTheory = reportData.reduce((sum, d) => sum + d.theoryQuantity, 0);
  const totalActual = reportData.reduce((sum, d) => sum + d.actualQuantity, 0);
  const totalProducts = reportData.reduce((sum, d) => sum + d.productCount, 0);

  const columns: ColumnDef<typeof reportData[0], unknown>[] = [
    {
      accessorKey: 'project.projectNo',
      header: '项目编号',
      cell: ({ row }) => row.original.project.projectNo,
    },
    {
      accessorKey: 'project.projectName',
      header: '项目名称',
      cell: ({ row }) => (
        <Button
          variant="ghost"
          size="sm"
          onClick={() => setSelectedProject(row.original.project)}
          className="text-blue-600 hover:text-blue-800"
        >
          {row.original.project.projectName}
        </Button>
      ),
    },
    {
      id: 'projectPeriod',
      header: '项目周期',
      cell: ({ row }) => `${row.original.project.startDate} ~ ${row.original.project.endDate}`,
    },
    {
      accessorKey: 'project.location',
      header: '项目地点',
      cell: ({ row }) => row.original.project.location,
    },
    {
      accessorKey: 'project.manager',
      header: '项目负责人',
      cell: ({ row }) => row.original.project.manager,
    },
    {
      id: 'projectStatus',
      header: '项目状态',
      cell: ({ row }) => {
        const status = projectStatusMap[row.original.project.status];
        return <Badge variant={status.variant}>{status.label}</Badge>;
      },
    },
    {
      accessorKey: 'orderCount',
      header: '订单数',
      cell: ({ row }) => (
        <span className="font-medium">{row.original.orderCount}</span>
      ),
    },
    {
      accessorKey: 'workOrderCount',
      header: '工单数',
      cell: ({ row }) => row.original.workOrderCount,
    },
    {
      accessorKey: 'requisitionCount',
      header: '领料单数',
      cell: ({ row }) => row.original.requisitionCount,
    },
    {
      accessorKey: 'theoryQuantity',
      header: '理论领料数量',
      cell: ({ row }) => (
        <span className="text-blue-600 font-medium">{row.original.theoryQuantity}</span>
      ),
    },
    {
      accessorKey: 'actualQuantity',
      header: '实际领料数量',
      cell: ({ row }) => (
        <span className="text-green-600 font-medium">{row.original.actualQuantity}</span>
      ),
    },
    {
      accessorKey: 'productCount',
      header: '涉及物料种类',
      cell: ({ row }) => row.original.productCount,
    },
    {
      id: 'diff',
      header: '差异(理论-实际)',
      cell: ({ row }) => {
        const diff = row.original.theoryQuantity - row.original.actualQuantity;
        return (
          <span className={diff > 0 ? 'text-orange-600' : diff < 0 ? 'text-red-600' : 'text-slate-500'}>
            {diff > 0 ? '+' : ''}{diff}
          </span>
        );
      },
    },
    {
      id: 'actions',
      header: '操作',
      cell: ({ row }) => (
        <Button
          variant="ghost"
          size="sm"
          onClick={() => setSelectedProject(row.original.project)}
        >
          详情
        </Button>
      ),
    },
  ];

  const projectOptions = exhibitionProjects.map(p => ({ value: p.id, label: p.projectName }));
  const statusOptions = [
    { value: '', label: '全部状态' },
    { value: 'planning', label: '筹备中' },
    { value: 'preparing', label: '准备中' },
    { value: 'ongoing', label: '进行中' },
    { value: 'completed', label: '已结束' },
  ];

  const handleExport = () => {
    if (reportData.length === 0) {
      alert('没有可导出的数据');
      return;
    }

    const exportData = reportData.map(item => ({
      '项目编号': item.project.projectNo,
      '项目名称': item.project.projectName,
      '项目周期': `${item.project.startDate} ~ ${item.project.endDate}`,
      '项目地点': item.project.location,
      '项目负责人': item.project.manager,
      '项目状态': projectStatusMap[item.project.status]?.label || item.project.status,
      '订单数': item.orderCount,
      '工单数': item.workOrderCount,
      '领料单数': item.requisitionCount,
      '理论领料数量': item.theoryQuantity,
      '实际领料数量': item.actualQuantity,
      '差异(理论-实际)': item.theoryQuantity - item.actualQuantity,
      '涉及物料种类': item.productCount,
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, '展会物资领用报表');
    XLSX.writeFile(wb, `展会物资领用报表_${new Date().toISOString().slice(0, 10)}.xlsx`);
  };

  // 详情弹窗中的项目订单数据
  const projectDetailData = useMemo(() => {
    if (!selectedProject) return null;
    const orders = outboundOrders.filter(o => o.projectId === selectedProject.id && o.status === 'submitted');

    const orderSummary = orders.map(order => ({
      orderNo: order.orderNo,
      type: order.type,
      typeLabel: orderTypeMap[order.type] || '其他',
      operator: order.operator,
      createTime: order.createTime,
      totalQuantity: order.details.reduce((s, d) => s + d.quantity, 0),
      details: order.details.map(d => {
        const product = products.find(p => p.id === d.productId);
        return {
          ...d,
          productName: product?.name || d.productName || '-',
          productCode: product?.code || d.productCode || '-',
          categoryName: product?.categoryName || '',
          unit: product?.unit || '',
        };
      }),
    }));

    return { project: selectedProject, orders: orderSummary };
  }, [selectedProject, outboundOrders, products]);

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-900">展会物资领用报表</h1>
        <Button variant="secondary" onClick={handleExport}>
          <Download size={16} />
          导出Excel
        </Button>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-4 flex-wrap">
            <Select
              options={projectOptions}
              value={projectFilter}
              onChange={(e) => setProjectFilter(e.target.value)}
              placeholder="全部项目"
            />
            <Select
              options={statusOptions}
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              placeholder="全部状态"
            />
            <Input
              type="date"
              value={dateRange.start}
              onChange={(e) => setDateRange({ ...dateRange, start: e.target.value })}
              className="w-40"
            />
            <span className="text-slate-500">至</span>
            <Input
              type="date"
              value={dateRange.end}
              onChange={(e) => setDateRange({ ...dateRange, end: e.target.value })}
              className="w-40"
            />
          </div>
        </CardHeader>
        <CardBody>
          {/* 统计概览 */}
          <div className="grid grid-cols-5 gap-4 mb-6">
            <div className="bg-gradient-to-br from-blue-50 to-blue-100 rounded-lg p-4">
              <p className="text-sm text-blue-600">项目数</p>
              <p className="text-2xl font-bold text-blue-700">{reportData.length}</p>
            </div>
            <div className="bg-gradient-to-br from-purple-50 to-purple-100 rounded-lg p-4">
              <p className="text-sm text-purple-600">订单总数</p>
              <p className="text-2xl font-bold text-purple-700">{totalOrders}</p>
            </div>
            <div className="bg-gradient-to-br from-cyan-50 to-cyan-100 rounded-lg p-4">
              <p className="text-sm text-cyan-600">理论领料数量</p>
              <p className="text-2xl font-bold text-cyan-700">{totalTheory}</p>
            </div>
            <div className="bg-gradient-to-br from-green-50 to-green-100 rounded-lg p-4">
              <p className="text-sm text-green-600">实际领料数量</p>
              <p className="text-2xl font-bold text-green-700">{totalActual}</p>
            </div>
            <div className="bg-gradient-to-br from-orange-50 to-orange-100 rounded-lg p-4">
              <p className="text-sm text-orange-600">涉及物料种类</p>
              <p className="text-2xl font-bold text-orange-700">{totalProducts}</p>
            </div>
          </div>

          <DataTable data={reportData} columns={columns} pageSize={15} />
        </CardBody>
      </Card>

      {/* 项目详情弹窗 */}
      <Modal
        open={!!selectedProject}
        onClose={() => setSelectedProject(null)}
        title="项目详情"
        size="max-w-4xl"
      >
        {projectDetailData && (
          <div className="space-y-4">
            {/* 项目基本信息 */}
            <div className="border border-slate-200 rounded-lg p-4 bg-slate-50">
              <h3 className="text-sm font-semibold text-slate-700 mb-3">项目基本信息</h3>
              <div className="grid grid-cols-2 gap-3 text-sm">
                <div className="flex items-center gap-2">
                  <FileText size={14} className="text-slate-400" />
                  <span className="text-slate-500">项目编号：</span>
                  <span className="font-medium">{projectDetailData.project.projectNo}</span>
                </div>
                <div className="flex items-center gap-2">
                  <FileText size={14} className="text-slate-400" />
                  <span className="text-slate-500">项目名称：</span>
                  <span className="font-medium">{projectDetailData.project.projectName}</span>
                </div>
                <div className="flex items-center gap-2">
                  <Calendar size={14} className="text-slate-400" />
                  <span className="text-slate-500">项目周期：</span>
                  <span>{projectDetailData.project.startDate} ~ {projectDetailData.project.endDate}</span>
                </div>
                <div className="flex items-center gap-2">
                  <MapPin size={14} className="text-slate-400" />
                  <span className="text-slate-500">项目地点：</span>
                  <span>{projectDetailData.project.location}</span>
                </div>
                <div className="flex items-center gap-2">
                  <User size={14} className="text-slate-400" />
                  <span className="text-slate-500">项目负责人：</span>
                  <span>{projectDetailData.project.manager}</span>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-slate-500">项目状态：</span>
                  <Badge variant={projectStatusMap[projectDetailData.project.status]?.variant || 'default'}>
                    {projectStatusMap[projectDetailData.project.status]?.label || projectDetailData.project.status}
                  </Badge>
                </div>
              </div>
            </div>

            {/* 项目订单列表 */}
            <div>
              <h3 className="text-sm font-semibold text-slate-700 mb-3">
                关联订单（{projectDetailData.orders.length}）
              </h3>
              {projectDetailData.orders.length === 0 ? (
                <div className="text-center py-8 text-slate-400 border border-slate-200 rounded-lg">
                  暂无关联订单
                </div>
              ) : (
                <div className="space-y-3 max-h-[500px] overflow-y-auto">
                  {projectDetailData.orders.map((order, idx) => (
                    <div key={idx} className="border border-slate-200 rounded-lg overflow-hidden">
                      <div className="bg-slate-50 px-4 py-2 flex items-center justify-between text-sm">
                        <div className="flex items-center gap-3">
                          <span className="font-medium">{order.orderNo}</span>
                          <Badge variant={order.type === 'workorder' ? 'warning' : 'default'}>
                            {order.typeLabel}
                          </Badge>
                        </div>
                        <div className="text-xs text-slate-500">
                          {order.createTime} | {order.operator}
                        </div>
                      </div>
                      <table className="w-full text-xs">
                        <thead className="bg-slate-50">
                          <tr>
                            <th className="px-3 py-2 text-left font-medium text-slate-600">物料编码</th>
                            <th className="px-3 py-2 text-left font-medium text-slate-600">物料名称</th>
                            <th className="px-3 py-2 text-left font-medium text-slate-600">规格</th>
                            <th className="px-3 py-2 text-left font-medium text-slate-600">单位</th>
                            <th className="px-3 py-2 text-right font-medium text-slate-600">数量</th>
                          </tr>
                        </thead>
                        <tbody>
                          {order.details.map((d, i) => (
                            <tr key={i} className="border-t border-slate-100">
                              <td className="px-3 py-2">{d.productCode}</td>
                              <td className="px-3 py-2">{d.productName}</td>
                              <td className="px-3 py-2">{d.categoryName || '-'}</td>
                              <td className="px-3 py-2">{(d as any).specification || '-'}</td>
                              <td className="px-3 py-2">{d.unit || '-'}</td>
                              <td className="px-3 py-2 text-right font-medium">{d.quantity}</td>
                            </tr>
                          ))}
                          <tr className="bg-slate-50 border-t border-slate-200">
                            <td colSpan={5} className="px-3 py-2 text-right font-medium text-slate-600">合计</td>
                            <td className="px-3 py-2 text-right font-bold text-blue-600">{order.totalQuantity}</td>
                          </tr>
                        </tbody>
                      </table>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div className="flex justify-end gap-3 pt-4 border-t">
              <Button variant="secondary" onClick={() => setSelectedProject(null)}>
                关闭
              </Button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}
