import { useState, useMemo } from 'react';
import { Plus, Search, Eye, Play, CheckSquare, Trash2 } from 'lucide-react';
import { ColumnDef } from '@tanstack/react-table';
import Card, { CardHeader, CardBody } from '@/components/common/Card';
import Button from '@/components/common/Button';
import Input from '@/components/common/Input';
import Select from '@/components/common/Select';
import DataTable from '@/components/common/DataTable';
import Modal from '@/components/common/Modal';
import Badge from '@/components/common/Badge';
import { useStore } from '@/store/useStore';
import { generateId } from '@/utils';

interface AssetCheckDetail {
  id: string;
  assetId: string;
  assetCode: string;
  assetName: string;
  specification?: string;
  unit: string;
  unitPrice: number;
  bookQuantity: number;
  bookAmount: number;
  checkQuantity: number;
  checkAmount: number;
  diffQuantity: number;
  diffAmount: number;
  status: 'unchecked' | 'checked';
}

interface AssetCheckOrder {
  id: string;
  orderNo: string;
  name: string;
  totalAssets: number;
  checkedAssets: number;
  profitAssets: number;
  lossAssets: number;
  profitAmount: number;
  lossAmount: number;
  totalBookAmount: number;
  totalCheckAmount: number;
  status: 'draft' | 'in_progress' | 'completed';
  createTime: string;
  remark: string;
  details: AssetCheckDetail[];
}

const generateCheckOrderNo = () => {
  const date = new Date();
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const random = Math.floor(Math.random() * 10000).toString().padStart(4, '0');
  return `ZCPD${year}${month}${day}${random}`;
};

const generateDetailsFromAssets = (
  assets: Array<{
    id: string;
    code: string;
    name: string;
    specification?: string;
    unit: string;
    amount: number;
  }>
): AssetCheckDetail[] => {
  return assets.map((asset) => {
    const bookQuantity = 1;
    const checkQuantity = bookQuantity;
    const diffQuantity = 0;
    const unitPrice = asset.amount;
    const bookAmount = unitPrice * bookQuantity;
    const checkAmount = bookAmount;
    const diffAmount = 0;

    return {
      id: generateId(),
      assetId: asset.id,
      assetCode: asset.code,
      assetName: asset.name,
      specification: asset.specification,
      unit: asset.unit,
      unitPrice,
      bookQuantity,
      bookAmount,
      checkQuantity,
      checkAmount,
      diffQuantity,
      diffAmount,
      status: 'unchecked',
    };
  });
};

export default function AssetCheck() {
  const { assetEquipments } = useStore();
  const [checkOrders, setCheckOrders] = useState<AssetCheckOrder[]>([]);

  const calculateOrderStats = (details: AssetCheckDetail[]) => {
    const totalAssets = details.length;
    const checkedAssets = details.filter(d => d.status === 'checked').length;
    const profitAssets = details.filter(d => d.diffQuantity > 0).length;
    const lossAssets = details.filter(d => d.diffQuantity < 0).length;
    const profitAmount = details.reduce((sum, d) => sum + (d.diffAmount > 0 ? d.diffAmount : 0), 0);
    const lossAmount = details.reduce((sum, d) => sum + (d.diffAmount < 0 ? Math.abs(d.diffAmount) : 0), 0);
    const totalBookAmount = details.reduce((sum, d) => sum + d.bookAmount, 0);
    const totalCheckAmount = details.reduce((sum, d) => sum + d.checkAmount, 0);

    return {
      totalAssets,
      checkedAssets,
      profitAssets,
      lossAssets,
      profitAmount,
      lossAmount,
      totalBookAmount,
      totalCheckAmount,
    };
  };
  const [orderNoFilter, setOrderNoFilter] = useState('');
  const [nameFilter, setNameFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [dateFromFilter, setDateFromFilter] = useState('');
  const [dateToFilter, setDateToFilter] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [detailModalOpen, setDetailModalOpen] = useState(false);
  const [viewingOrder, setViewingOrder] = useState<AssetCheckOrder | null>(null);
  const [editingOrder, setEditingOrder] = useState<AssetCheckOrder | null>(null);

  const [formData, setFormData] = useState({
    name: '',
    remark: '',
  });

  const stats = useMemo(() => {
    const now = new Date();
    const currentMonth = now.getMonth();
    const currentYear = now.getFullYear();

    const monthOrders = checkOrders.filter(o => {
      const d = new Date(o.createTime);
      return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    const inProgress = checkOrders.filter(o => o.status === 'in_progress').length;
    const completed = checkOrders.filter(o => o.status === 'completed').length;
    const totalProfit = checkOrders.reduce((sum, o) => sum + o.profitAssets, 0);
    const totalLoss = checkOrders.reduce((sum, o) => sum + o.lossAssets, 0);

    return {
      monthCount: monthOrders.length,
      inProgress,
      completed,
      profit: totalProfit,
      loss: totalLoss,
    };
  }, [checkOrders]);

  const filteredData = checkOrders
    .filter(o => !orderNoFilter || o.orderNo.toLowerCase().includes(orderNoFilter.toLowerCase()))
    .filter(o => !nameFilter || o.name.toLowerCase().includes(nameFilter.toLowerCase()))
    .filter(o => !statusFilter || o.status === statusFilter)
    .filter(o => !dateFromFilter || o.createTime >= dateFromFilter)
    .filter(o => !dateToFilter || o.createTime <= dateToFilter);

  const statusOptions = [
    { value: '', label: '全部状态' },
    { value: 'draft', label: '草稿' },
    { value: 'in_progress', label: '盘点中' },
    { value: 'completed', label: '已完成' },
  ];

  const statusBadgeVariants: Record<string, 'default' | 'success' | 'danger' | 'warning' | 'info'> = {
    draft: 'default',
    in_progress: 'warning',
    completed: 'success',
  };

  const statusLabels: Record<string, string> = {
    draft: '草稿',
    in_progress: '盘点中',
    completed: '已完成',
  };

  const columns: ColumnDef<AssetCheckOrder, unknown>[] = [
    { accessorKey: 'orderNo', header: '盘点单号' },
    { accessorKey: 'name', header: '盘点名称' },
    { accessorKey: 'totalAssets', header: '资产总数' },
    { accessorKey: 'checkedAssets', header: '已盘数' },
    {
      accessorKey: 'profitAssets',
      header: '盘盈数',
      cell: ({ row }) => (
        <span className={row.original.profitAssets > 0 ? 'text-green-600 font-medium' : ''}>
          {row.original.profitAssets}
        </span>
      ),
    },
    {
      accessorKey: 'lossAssets',
      header: '盘亏数',
      cell: ({ row }) => (
        <span className={row.original.lossAssets > 0 ? 'text-red-600 font-medium' : ''}>
          {row.original.lossAssets}
        </span>
      ),
    },
    {
      accessorKey: 'status',
      header: '状态',
      cell: ({ row }) => (
        <Badge variant={statusBadgeVariants[row.original.status]}>
          {statusLabels[row.original.status]}
        </Badge>
      ),
    },
    { accessorKey: 'createTime', header: '创建日期' },
    {
      id: 'actions',
      header: '操作',
      cell: ({ row }) => (
        <div className="flex items-center gap-2 flex-wrap">
          <Button variant="ghost" size="sm" onClick={() => handleView(row.original)}>
            <Eye size={14} /> 查看
          </Button>
          {row.original.status === 'draft' && (
            <>
              <Button variant="ghost" size="sm" onClick={() => handleStart(row.original)}>
                <Play size={14} /> 开始盘点
              </Button>
              <Button variant="ghost" size="sm" onClick={() => handleDelete(row.original)}>
                <span className="text-red-500"><Trash2 size={14} /> 删除</span>
              </Button>
            </>
          )}
          {row.original.status === 'in_progress' && (
            <Button variant="ghost" size="sm" onClick={() => handleComplete(row.original)}>
              <CheckSquare size={14} /> 完成盘点
            </Button>
          )}
        </div>
      ),
    },
  ];

  const handleOpenModal = () => {
    setEditingOrder(null);
    setFormData({
      name: '',
      remark: '',
    });
    setModalOpen(true);
  };

  const handleView = (order: AssetCheckOrder) => {
    setViewingOrder(order);
    setDetailModalOpen(true);
  };

  const handleStart = (order: AssetCheckOrder) => {
    if (confirm(`确认开始盘点"${order.name}"吗？`)) {
      setCheckOrders(prev => prev.map(o =>
        o.id === order.id
          ? { ...o, status: 'in_progress' }
          : o
      ));
    }
  };

  const handleComplete = (order: AssetCheckOrder) => {
    if (confirm(`确认完成盘点"${order.name}"吗？完成后将无法修改。`)) {
      const stats = calculateOrderStats(order.details);

      setCheckOrders(prev => prev.map(o =>
        o.id === order.id
          ? { ...o, status: 'completed', ...stats }
          : o
      ));
      
      if (viewingOrder && viewingOrder.id === order.id) {
        setViewingOrder({ ...order, status: 'completed', ...stats });
      }
    }
  };

  const handleDelete = (order: AssetCheckOrder) => {
    if (confirm(`确认删除盘点单"${order.name}"吗？`)) {
      setCheckOrders(prev => prev.filter(o => o.id !== order.id));
    }
  };

  const handleSubmit = () => {
    if (!formData.name) {
      alert('请填写盘点名称');
      return;
    }

    const assets = assetEquipments;
    const details = generateDetailsFromAssets(assets);
    const stats = calculateOrderStats(details);

    const newOrder: AssetCheckOrder = {
      id: generateId(),
      orderNo: generateCheckOrderNo(),
      name: formData.name,
      ...stats,
      status: 'draft',
      createTime: new Date().toISOString().slice(0, 10),
      remark: formData.remark,
      details,
    };

    setCheckOrders(prev => [newOrder, ...prev]);
    setModalOpen(false);
  };

  const updateDetailQuantity = (detailId: string, value: number) => {
    if (!viewingOrder) return;

    const newDetails = viewingOrder.details.map(d => {
      if (d.id === detailId) {
        const checkQuantity = Math.max(0, value);
        const diffQuantity = checkQuantity - d.bookQuantity;
        const checkAmount = d.unitPrice * checkQuantity;
        const diffAmount = checkAmount - d.bookAmount;
        return { ...d, checkQuantity, checkAmount, diffQuantity, diffAmount, status: 'checked' as const };
      }
      return d;
    });

    const stats = calculateOrderStats(newDetails);
    setViewingOrder({ ...viewingOrder, details: newDetails, ...stats });

    setCheckOrders(prev => prev.map(o =>
      o.id === viewingOrder.id ? { ...o, details: newDetails, ...stats } : o
    ));
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold text-slate-900">资产盘点管理</h1>
        <Button onClick={handleOpenModal}>
          <Plus size={16} />
          新增盘点
        </Button>
      </div>

      {/* 统计卡片 */}
      <div className="grid grid-cols-4 gap-4">
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">本月盘点单</div>
            <div className="text-2xl font-bold text-slate-900">{stats.monthCount}</div>
            <div className="text-xs text-slate-400 mt-1">单</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">盘点中</div>
            <div className="text-2xl font-bold text-amber-600">{stats.inProgress}</div>
            <div className="text-xs text-slate-400 mt-1">进行中</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">已完成</div>
            <div className="text-2xl font-bold text-green-600">{stats.completed}</div>
            <div className="text-xs text-slate-400 mt-1">已完成</div>
          </CardBody>
        </Card>
        <Card>
          <CardBody>
            <div className="text-sm text-slate-500 mb-1">盘盈/盘亏</div>
            <div className="text-2xl font-bold">
              <span className="text-green-600">+{stats.profit}</span>
              <span className="text-slate-400 mx-1">/</span>
              <span className="text-red-600">-{stats.loss}</span>
            </div>
            <div className="text-xs text-slate-400 mt-1">差异数</div>
          </CardBody>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <div className="flex items-center gap-4 flex-wrap">
            <div className="relative">
              <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input
                placeholder="盘点单号..."
                value={orderNoFilter}
                onChange={(e) => setOrderNoFilter(e.target.value)}
                className="pl-9 w-48"
              />
            </div>
            <div className="relative">
              <Search size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
              <Input
                placeholder="盘点名称..."
                value={nameFilter}
                onChange={(e) => setNameFilter(e.target.value)}
                className="pl-9 w-48"
              />
            </div>
            <Select
              options={statusOptions}
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              placeholder="全部状态"
              className="w-36"
            />
            <div className="flex items-center gap-2">
              <Input
                type="date"
                value={dateFromFilter}
                onChange={(e) => setDateFromFilter(e.target.value)}
                className="w-40"
              />
              <span className="text-slate-400">至</span>
              <Input
                type="date"
                value={dateToFilter}
                onChange={(e) => setDateToFilter(e.target.value)}
                className="w-40"
              />
            </div>
          </div>
        </CardHeader>
        <CardBody>
          <DataTable data={filteredData} columns={columns} pageSize={10} />
        </CardBody>
      </Card>

      {/* 新增盘点弹窗 */}
      <Modal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        title="新增盘点单"
        size="md"
      >
        <div className="space-y-4 min-w-[500px]">
          <Input
            label="盘点名称"
            value={formData.name}
            onChange={(e) => setFormData({ ...formData, name: e.target.value })}
            placeholder="请输入盘点名称"
          />
          <div className="space-y-1">
            <label className="block text-sm font-medium text-slate-700">备注</label>
            <textarea
              value={formData.remark}
              onChange={(e) => setFormData({ ...formData, remark: e.target.value })}
              placeholder="请输入备注信息"
              rows={3}
              className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent resize-none"
            />
          </div>
          <div className="flex justify-end gap-3 pt-2">
            <Button variant="secondary" onClick={() => setModalOpen(false)}>
              取消
            </Button>
            <Button onClick={handleSubmit}>
              保存
            </Button>
          </div>
        </div>
      </Modal>

      {/* 盘点详情弹窗 */}
      <Modal
        open={detailModalOpen}
        onClose={() => setDetailModalOpen(false)}
        title="盘点明细"
        size="xl"
      >
        {viewingOrder && (
          <div className="space-y-4 min-w-[1000px]">
            <div className="grid grid-cols-3 gap-4 text-sm p-4 bg-slate-50 rounded-lg">
              <div>
                <span className="text-slate-500">盘点单号：</span>
                <span className="font-medium">{viewingOrder.orderNo}</span>
              </div>
              <div>
                <span className="text-slate-500">盘点名称：</span>
                <span className="font-medium">{viewingOrder.name}</span>
              </div>
              <div>
                <span className="text-slate-500">状态：</span>
                <Badge variant={statusBadgeVariants[viewingOrder.status]}>
                  {statusLabels[viewingOrder.status]}
                </Badge>
              </div>
              <div>
                <span className="text-slate-500">资产总数：</span>
                <span className="font-medium">{viewingOrder.totalAssets}</span>
              </div>
              <div>
                <span className="text-slate-500">已盘数：</span>
                <span className="font-medium">{viewingOrder.checkedAssets}</span>
              </div>
              <div>
                <span className="text-slate-500">盘盈数：</span>
                <span className="font-medium text-green-600">{viewingOrder.profitAssets}</span>
              </div>
              <div>
                <span className="text-slate-500">盘亏数：</span>
                <span className="font-medium text-red-600">{viewingOrder.lossAssets}</span>
              </div>
              <div>
                <span className="text-slate-500">账面总金额：</span>
                <span className="font-medium">¥{viewingOrder.totalBookAmount.toFixed(2)}</span>
              </div>
              <div>
                <span className="text-slate-500">实盘总金额：</span>
                <span className="font-medium">¥{viewingOrder.totalCheckAmount.toFixed(2)}</span>
              </div>
              <div>
                <span className="text-slate-500">盘盈金额：</span>
                <span className="font-medium text-green-600">+¥{viewingOrder.profitAmount.toFixed(2)}</span>
              </div>
              <div>
                <span className="text-slate-500">盘亏金额：</span>
                <span className="font-medium text-red-600">-¥{viewingOrder.lossAmount.toFixed(2)}</span>
              </div>
            </div>

            {viewingOrder.status === 'completed' && (
              <div className="p-4 bg-amber-50 border border-amber-200 rounded-lg">
                <div className="text-sm font-medium text-amber-800 mb-2">盘点结果说明（原型展示）</div>
                <div className="text-sm text-amber-700 space-y-1">
                  <p>• 盘盈资产 {viewingOrder.profitAssets} 项，盘盈金额 ¥{viewingOrder.profitAmount.toFixed(2)}，需后续入账处理</p>
                  <p>• 盘亏资产 {viewingOrder.lossAssets} 项，盘亏金额 ¥{viewingOrder.lossAmount.toFixed(2)}，需查明原因并审批</p>
                  <p>• 盘点完成后，系统将根据盘盈盘亏情况调整资产台账（原型阶段暂不实际调整）</p>
                </div>
              </div>
            )}

            {viewingOrder.details.length > 0 ? (
              <div className="border border-slate-200 rounded-lg overflow-x-auto">
                <table className="w-full text-sm min-w-[900px]">
                  <thead>
                    <tr className="bg-slate-50 text-slate-600">
                      <th className="px-3 py-3 text-left font-medium whitespace-nowrap">资产编码</th>
                      <th className="px-3 py-3 text-left font-medium whitespace-nowrap">资产名称</th>
                      <th className="px-3 py-3 text-left font-medium whitespace-nowrap">规格型号</th>
                      <th className="px-3 py-3 text-center font-medium whitespace-nowrap">单位</th>
                      <th className="px-3 py-3 text-right font-medium whitespace-nowrap">单价</th>
                      <th className="px-3 py-3 text-center font-medium whitespace-nowrap">账面数量</th>
                      <th className="px-3 py-3 text-right font-medium whitespace-nowrap">账面金额</th>
                      <th className="px-3 py-3 text-center font-medium whitespace-nowrap">实盘数量</th>
                      <th className="px-3 py-3 text-right font-medium whitespace-nowrap">实盘金额</th>
                      <th className="px-3 py-3 text-center font-medium whitespace-nowrap">差异数量</th>
                      <th className="px-3 py-3 text-right font-medium whitespace-nowrap">差异金额</th>
                      <th className="px-3 py-3 text-center font-medium whitespace-nowrap">状态</th>
                    </tr>
                  </thead>
                  <tbody>
                    {viewingOrder.details.map((detail) => (
                      <tr key={detail.id} className="border-t border-slate-100 hover:bg-slate-50">
                        <td className="px-3 py-3 whitespace-nowrap">{detail.assetCode}</td>
                        <td className="px-3 py-3 whitespace-nowrap">{detail.assetName}</td>
                        <td className="px-3 py-3 whitespace-nowrap text-slate-500">{detail.specification || '-'}</td>
                        <td className="px-3 py-3 text-center whitespace-nowrap">{detail.unit}</td>
                        <td className="px-3 py-3 text-right whitespace-nowrap">¥{detail.unitPrice.toFixed(2)}</td>
                        <td className="px-3 py-3 text-center whitespace-nowrap">{detail.bookQuantity}</td>
                        <td className="px-3 py-3 text-right whitespace-nowrap">¥{detail.bookAmount.toFixed(2)}</td>
                        <td className="px-3 py-3 text-center whitespace-nowrap">
                          {viewingOrder.status === 'in_progress' ? (
                            <input
                              type="number"
                              min="0"
                              value={detail.checkQuantity}
                              onChange={(e) => updateDetailQuantity(detail.id, parseInt(e.target.value) || 0)}
                              className="w-16 px-2 py-1 border border-slate-300 rounded text-center focus:outline-none focus:ring-2 focus:ring-blue-500"
                            />
                          ) : (
                            detail.checkQuantity
                          )}
                        </td>
                        <td className="px-3 py-3 text-right whitespace-nowrap">¥{detail.checkAmount.toFixed(2)}</td>
                        <td className={`px-3 py-3 text-center font-medium whitespace-nowrap ${
                          detail.diffQuantity > 0 ? 'text-green-600' :
                          detail.diffQuantity < 0 ? 'text-red-600' : ''
                        }`}>
                          {detail.diffQuantity > 0 ? `+${detail.diffQuantity}` : detail.diffQuantity}
                        </td>
                        <td className={`px-3 py-3 text-right font-medium whitespace-nowrap ${
                          detail.diffAmount > 0 ? 'text-green-600' :
                          detail.diffAmount < 0 ? 'text-red-600' : ''
                        }`}>
                          {detail.diffAmount > 0 ? `+¥${detail.diffAmount.toFixed(2)}` : `¥${detail.diffAmount.toFixed(2)}`}
                        </td>
                        <td className="px-3 py-3 text-center whitespace-nowrap">
                          <Badge variant={detail.status === 'checked' ? 'success' : 'default'}>
                            {detail.status === 'checked' ? '已盘' : '未盘'}
                          </Badge>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="py-12 text-center text-slate-400">
                暂无盘点明细
              </div>
            )}

            <div className="flex justify-end gap-3 pt-2">
              <Button variant="secondary" onClick={() => setDetailModalOpen(false)}>
                关闭
              </Button>
            </div>
          </div>
        )}
      </Modal>
    </div>
  );
}
