import { useMemo, useState } from 'react';
import { Search, RefreshCw } from 'lucide-react';
import { DataTable, ColumnDef } from '@/components/common/DataTable';
import Input from '@/components/common/Input';
import Select from '@/components/common/Select';
import Button from '@/components/common/Button';
import { useStore } from '@/store/useStore';

type Row = {
  productCode: string;
  productName: string;
  specification: string;
  unit: string;
  warehouse: string;
  projectId?: string;
  projectName?: string;
  total: number;
};

export default function StockReportPage() {
  const batchInventories = useStore((s) => s.batchInventories);
  const products = useStore((s) => s.products);
  const warehouses = useStore((s) => s.warehouses);
  const exhibitionProjects = useStore((s) => s.exhibitionProjects);

  // 筛选状态
  const [filterProductCode, setFilterProductCode] = useState('');
  const [filterProductName, setFilterProductName] = useState('');
  const [filterWarehouse, setFilterWarehouse] = useState('');
  const [filterProject, setFilterProject] = useState('');

  const rows: Row[] = useMemo(() => {
    // 按产品+仓库+项目聚合库存
    const aggregated: Record<string, { total: number; lastInboundTime?: string }> = {};
    batchInventories.forEach((b) => {
      const key = `${b.productId}-${b.warehouseId}-${b.projectId || 'none'}`;
      const current = aggregated[key];
      const newTime = b.inboundTime || '';
      aggregated[key] = {
        total: (current?.total || 0) + b.quantity,
        lastInboundTime: current?.lastInboundTime
          ? (newTime > current.lastInboundTime ? newTime : current.lastInboundTime)
          : newTime,
      };
    });

    return Object.entries(aggregated)
      .map(([key, data]) => {
        const [productId, warehouseId, projectId] = key.split('-');
        const p = products.find((x) => x.id === productId);
        const w = warehouses.find((x) => x.id === warehouseId);
        const proj = projectId !== 'none' 
          ? batchInventories.find(b => b.projectId === projectId)
          : null;
        return {
          productCode: p?.code || productId,
          productName: p?.name || '-',
          specification: p?.specification || '-',
          unit: p?.unit || '-',
          warehouse: w?.name || warehouseId,
          projectId: projectId !== 'none' ? projectId : undefined,
          projectName: proj?.projectName,
          total: data.total,
        };
      })
      .filter((row) => {
        // 产品编码筛选
        if (filterProductCode && !row.productCode.toLowerCase().includes(filterProductCode.toLowerCase())) {
          return false;
        }
        // 产品名称筛选
        if (filterProductName && !row.productName.toLowerCase().includes(filterProductName.toLowerCase())) {
          return false;
        }
        // 仓库筛选
        if (filterWarehouse) {
          const w = warehouses.find((x) => x.id === filterWarehouse);
          if (w && row.warehouse !== w.name) return false;
        }
        // 项目筛选
        if (filterProject && row.projectId !== filterProject) {
          return false;
        }
        return true;
      });
  }, [batchInventories, products, warehouses, filterProductCode, filterProductName, filterWarehouse, filterProject]);

  const columns: ColumnDef<Row>[] = [
    { key: 'productCode', title: '产品编码' },
    { key: 'productName', title: '产品名称' },
    { key: 'specification', title: '规格' },
    { key: 'unit', title: '单位' },
    { key: 'warehouse', title: '仓库' },
    { key: 'projectName', title: '所属项目', render: (row) => row.projectName || '-' },
    { key: 'total', title: '总库存', align: 'right' },
  ];

  // 下拉选项
  const warehouseOptions = [
    { value: '', label: '全部仓库' },
    ...warehouses.map((w) => ({ value: w.id, label: w.name })),
  ];

  const projectOptions = [
    { value: '', label: '全部项目' },
    ...exhibitionProjects.map((p) => ({ value: p.id, label: p.projectName })),
  ];

  // 重置筛选
  const handleReset = () => {
    setFilterProductCode('');
    setFilterProductName('');
    setFilterWarehouse('');
    setFilterProject('');
  };

  // 总计
  const totalQty = rows.reduce((sum, row) => sum + row.total, 0);

  return (
    <div className="p-4">
      <div className="mb-3 flex items-center justify-between">
        <h2 className="text-lg font-semibold text-[#303133]">库存报表</h2>
        <div className="text-sm text-[#606266]">
          共 <span className="font-semibold text-[#2f54eb]">{rows.length}</span> 条记录，
          合计库存 <span className="font-semibold text-[#67c23a]">{totalQty.toLocaleString()}</span>
        </div>
      </div>

      {/* 筛选区域 */}
      <div className="bg-[#fafbfc] border border-[#ebeef5] rounded-lg p-4 mb-4">
        <div className="grid grid-cols-4 gap-3">
          <Input
            placeholder="产品编码"
            value={filterProductCode}
            onChange={(e) => setFilterProductCode(e.target.value)}
          />
          <Input
            placeholder="产品名称"
            value={filterProductName}
            onChange={(e) => setFilterProductName(e.target.value)}
          />
          <Select
            options={warehouseOptions}
            value={filterWarehouse}
            onChange={(e) => setFilterWarehouse(e.target.value)}
          />
          <Select
            options={projectOptions}
            value={filterProject}
            onChange={(e) => setFilterProject(e.target.value)}
          />
        </div>
        <div className="flex justify-end gap-2 mt-3">
          <Button variant="outline" size="sm" onClick={handleReset}>
            <RefreshCw size={14} />
            重置
          </Button>
        </div>
      </div>

      <DataTable data={rows} columns={columns} />
    </div>
  );
}
